// articles.js — Zero One Magazine — 10 full profiles by 王梓蓉.

const ARTICLES = [
  {
    id: 'wang-zhuolun',
    kind: 'profile',
    date: 'Mar 2, 2026',
    read: 12,
    lang: 'zh',
    illus: 'assets/illustrations/portrait-contour-1.svg',
    heroIllus: 'assets/illustrations/portrait-contour-1.svg',
    title: '王卓伦：战地没有"玫瑰"，只有使命',
    titleEn: 'Wang Zhuolun · No roses in a war zone, only duty',
    dek: '她是新华社驻中东的战地记者，在硝烟与枪声中，她用镜头和文字记录着这个世界最不平静的角落。',
    tags: ["profile","战地记者","新华社","中东"],
    body: [
      { type: 'p', text: '2026年3月2日，新华社驻耶路撒冷首席记者王卓伦站在全国三八红旗手颁奖台上。台下掌声雷动，她却恍惚了一瞬——就在两天前，中东战火再起。脚踏祖国安宁的土地，呼吸着没有硝烟的空气，她比任何人都更懂得这份和平的珍贵。也正因如此，她更牵挂着战火中的人们，心念着万里之外的战地,“这几天战事激烈，我一直密切关注着前线局势。”' },
      { type: 'p', text: '一边是战火纷飞，一边是安宁祥和，两个世界仿佛被一道无形的屏障彻底隔开。而她，正是那个不断穿越这道屏障的人。' },
      { type: 'h', text: '战地“玫瑰”，向险而行' },
      { type: 'p', text: '从牛津大学硕士毕业后，王卓伦于2014年进入新华社，成为一名外交外事时政记者。此后近七年，她圆满完成党和国家领导人数百场外交外事和出国访问的报道任务，身影常出现在中南海、人民大会堂等重要场合，笔下记录的皆是国家重大新闻事件。' },
      { type: 'p', text: '2021年，她做出一个令人意外的决定：主动请缨，赴条件艰苦、局势动荡的中东战乱地区工作。“很多人关心我，不理解我为什么放弃这样好的岗位，去那种地方吃苦受累。”' },
      { type: 'p', text: '她被问得最多的问题是：身为女性，为何一定要奔赴战地？尤其是从相对光鲜、安稳的时政报道岗位，转向充满不确定性和安全隐患的战地一线——要知道，烽火连天的中东，尤其是导弹随时可能降临的巴以地区，是全球最危险的新闻现场之一。' },
      { type: 'p', text: '答案或许藏在她的童年里。她坦言，自己从小就崇拜花木兰、刘胡兰、穆桂英这样的巾帼豪杰。父母未曾刻意教导她何为“女性力量”，却潜移默化中养出了她骨子里的独立与倔强。那颗想成为“女侠”“女英雄”的种子，早已在心底悄然生根。' },
      { type: 'p', text: '从时政记者到战地记者，从中国外交政策的发布端到国际新闻最前沿，从常年身着正装到常被厚重防弹装备压得满身汗水……在王卓伦看来，这种职业转变，是职责的延伸、使命的传承，更是中国记者向险而行、为国发声的必然选择。' },
      { type: 'p', text: '变的是岗位与环境，不变的是她内心深处对记者职业的深沉热爱与坚定责任担当。' },
      { type: 'p', text: '王卓伦说：“战地报道远不止冲到现场拍摄惊心动魄的画面那么简单，更需要清醒坚定的政治判断、对大局的精准把握，以及在信息洪流中保持清醒与定力。”七年时政记者生涯磨砺出的严谨敏锐，成为她在战火中前行的底气。' },
      { type: 'h', text: '烽烟漫天，逆行而上' },
      { type: 'p', text: '人们常将战地女性称作“战地玫瑰”，但真正亲历战争的人深知，那里没有绽放的玫瑰，只有沉甸甸的使命。浪漫的隐喻，掩盖不了战争的残酷，更不能降低职业应有的标准。' },
      { type: 'p', text: '2023年10月7日，数十年来最惨烈、持续时间最长、伤亡人数最多的一轮巴以冲突爆发。王卓伦义无反顾冲在最前线。彼时，险情频发，乱局中没有安保、没有司机，多数时候甚至没有摄像陪同，她一次次独自驾车赶赴战火现场。' },
      { type: 'p', text: '若参与军方批准的加沙边境采访，记者必须签订“生死协议”：一旦出现意外，军方概不负责。这样的协议，她已记不清签了多少次。' },
      { type: 'p', text: '有一次，凌晨两三点，大量导弹突然来袭。同楼邻居纷纷往防空洞奔跑，她却毅然冲上街头，“这是我的本能，我只想把这一幕记录下来，把珍贵的现场画面留存下来。”' },
      { type: 'p', text: '还有一次，她驾车刚驶过加沙边境一段高速公路，短短几分钟后，该路段便遭轰炸，整条公路被拦腰截断、面目全非……' },
      { type: 'p', text: '“挺庆幸的。”她只平静地说了这几个字。' },
      { type: 'p', text: '在那片土地上，战局激烈时，每天有上百枚导弹、火箭弹、无人机从不同方向越境袭来，持枪、持刀袭击及驾车冲撞事件时有发生。死亡，成了日常的一部分。' },
      { type: 'p', text: '而她，在这样的日常里，坚守了近六年。' },
      { type: 'p', text: '“比起肉眼可见的危险，更难熬的是精神上的煎熬。”她说，那是一种无尽的紧绷，一种无法深度入眠的常态。即便在梦中，炮火的阴影也挥之不去——她常常梦到导弹来袭，梦见编辑部催稿，甚至梦见自己坐在停火谈判桌前。' },
      { type: 'p', text: '每当休假回国，她都会陷入恍惚。春节期间，鞭炮噼里啪啦作响，她会下意识绷紧身体——那声音太像密集的枪声；烟花升上夜空的瞬间，她的瞳孔会骤然收缩——那轨迹，与导弹拦截系统升空时一模一样。' },
      { type: 'p', text: '“之前很长一段时间，听到救护车、警车的鸣笛，甚至电动车启动的瞬间声响，都会突然感到不适或警觉。”她说，“随着在战地待的时间越来越长，现在心理状态好了一些，但本能的应激反应仍难以完全摆脱。”' },
      { type: 'p', text: '唯有从战火中走出的人，才最懂和平的可贵。' },
      { type: 'p', text: '“这几天走在北京初春的街头，我真的格外感动、格外感慨。”她眼眶微红，“阳光伴着微风，街上的人自由行走……这些或许都是平凡的场景，平凡到大家习以为常，但对我而言，每一处都藏着微小的幸福，每一处都彰显着平凡的珍贵。”' },
      { type: 'p', text: '在全国三八红旗手颁奖大会上，当全体人员起立唱国歌时，她感到体内热血奔涌，热泪悄然滑落。' },
      { type: 'h', text: '铁笔无畏，我自中国' },
      { type: 'p', text: '在战地待久了，王卓伦见过太多令人心碎的画面。导弹来袭时，她看见邻居们仓皇涌入防空设施，有时里面挤满了人，挤不进去的人只能蜷缩在楼道里。夜色中，一位母亲怀抱着嗷嗷大哭的婴儿，手足无措却无能为力，只能一遍遍地抱紧孩子。' },
      { type: 'p', text: '还有一幕，她至今难忘。防空警报响起时，一位母亲没有惊慌，随手抓起一个洋娃娃递给孩子，用轻松甚至略带幽默的语气说：“来，我们玩个游戏。”就像电影《美丽人生》里那样，用温柔的谎言为孩子搭建起虚假的安全世界，只为让他们少一分恐惧，少留一丝童年阴影。' },
      { type: 'p', text: '“那些母亲真的很伟大。”王卓伦的声音低沉下来，“她们挡不住战火，唯一能做的，就是尽量不让孩子知晓真相。”' },
      { type: 'p', text: '可孩子们真的一无所知吗？当地朋友带孩子外出时，孩子开口的第一句话往往是：“这里有导弹吗？这里有防空洞吗？如果突然有危险，我们去哪里躲？”' },
      { type: 'p', text: '“战争已经成了他们童年的一部分。”她说，“他们的神经，时刻都绷得紧紧的。”' },
      { type: 'p', text: '在巴以战地，东方面孔本就稀少，东方女性面孔更是罕见。每当王卓伦出现在爆炸现场，当地人都会好奇地围上来：“你是谁？你从哪里来？”' },
      { type: 'p', text: '她总会平静而坚定地回答：“我来自中国。”' },
      { type: 'p', text: '那一刻，强烈的自豪感便会油然而生。“国际新闻记者肩负着‘讲好中国故事、传播好中国声音’的使命，其实，只要有中国记者出现在战地一线，本身就是一种中国故事。”' },
      { type: 'p', text: '跑前线多了，当地的警察、急救人员、加油站员工都认识了她，常会笑着说：“中国记者，你又来了！”' },
      { type: 'p', text: '“他们未必记得我的名字，也不必记得我的名字，因为‘中国记者’这四个字，就是我的名字。能在局势复杂的战地，为‘中国’二字增添新闻注脚，便是对我们驻外记者最高的肯定。”王卓伦说。' },
      { type: 'p', text: '有人问她：战地如此危险，你还要坚持多久？“只要工作需要，我就会一直坚持下去。”她的回答没有半秒犹豫。' },
      { type: 'p', text: '战地报道，拼的不仅是勇气，更是经验、判断力，是枪林弹雨中的沉着冷静。这些，都需要时间沉淀。“越有经验，越被需要。”她说。' },
      { type: 'p', text: '2024年10月17日晚，哈马斯头号人物辛瓦尔在以军行动中身亡。新华社英文快讯全球首发——比路透社、法新社、美联社以及以色列本土媒体均早一步。这背后，是王卓伦与同事们日复一日的坚守、深耕与默契配合。' },
      { type: 'p', text: '“好的战地报道，必然是厚积薄发。”作为文字记者，她更多时候在镜头背后默默用笔锤炼业务，却始终以全媒体记者的标准要求自己。“要会写、会拍、会剪、会分析，要有冷静的头脑，在新闻现场多思考、多询问、多倾听，不盲目跟随单一信息源。”' },
      { type: 'p', text: '此刻，中东战火正酣。王卓伦归心似箭：“我现在迫切希望尽快回到工作岗位，重返战地一线。”尽管领空关闭、航班停飞，具体返程方案仍需协商，但她的心，早已飞回那片伤痕累累的土地。' },
      { type: 'p', text: '因为她坚信：唯有让更多人看见战争的残酷，才能让更多人懂得和平的珍贵。' },
      { type: 'p', text: '她不是温室里的玫瑰，是向着真相、向着使命、向着战场逆行的——中国记者。' },
    ],
  },
  {
    id: 'he-chaoqiong',
    kind: 'profile',
    date: 'Oct 20, 2024',
    read: 14,
    lang: 'zh',
    illus: 'assets/illustrations/portrait-contour-2.svg',
    heroIllus: 'assets/illustrations/portrait-contour-2.svg',
    title: '何超琼：澳门风采的璀璨续写者',
    titleEn: 'Pansy Ho · Continuing Macau\'s brilliance',
    dek: '从澳门到大湾区，从商业到文化，何超琼以新一代澳门人的身份，续写着这座城的璀璨风采。',
    tags: ["profile","澳门","大湾区","文化"],
    body: [
      { type: 'p', text: '今年是澳门回归祖国 25 周年，是《粤港澳大湾区发展规划纲要》实施 5 周年。何超琼 见证了澳门回归祖国后的蓬勃发展，更以“大湾区人”的责任与担当，躬身推动港澳与内地的深度融合与发展。' },
      { type: 'p', text: '何超琼：第十四届全国政协常委，全国工商联副主席、全国妇联常委、执委。信德集团行政主席兼董事总经理、美高梅中国联席董事长及执行董事' },
      { type: 'h', text: '何超琼：澳门风采的璀璨续写者' },
      { type: 'p', text: '在中华人民共和国成立75周年暨澳门特别行政区成立25周年之际，保利文化与美高梅联合打造的 “保利美高梅博物馆”在澳门美高梅天幕广场隆重举行开幕式。一身洁白套装的何超琼在台上向来自海内外的200多位嘉宾分享博物馆建设的心路历程。' },
      { type: 'p', text: '“澳门是中西方文化交流的先驱，是“海上丝绸之路”上的璀璨明珠，更是传承中华优秀传统文化、呈现非物质文化遗产之美的世界级文旅地标，它见证五千年中国文明的辉煌，还会将中华文化的故事传播得更广、更远。”' },
      { type: 'p', text: '虽然有手稿，但说到此时，何超琼眼神坚定地望着台下的每一位来宾。念念不忘，必有回响。站在圆明园四兽首铜像等近30件国家一级文物之中，何超琼心中泛起许多回忆，“猪首是爸爸当年买回来捐出去的，象征我们回归的初心！”' },
      { type: 'h', text: '从澳门出发，讲好中国文旅故事' },
      { type: 'p', text: '1999 年澳门回归，那一年，何超琼开始担任德信集团董事总经理。她敏锐地意识到，旅游市场开始进入结构性转型，并积极顺应这一发展变化，开创了旅游业从单一产业到多元化的先河。作为澳门高端酒店行业的先行者，为实现“增强中国旅游业全球竞争力”的目标，她和一批有同样信念的民营企业家筹办了澳门世界旅游经济论坛，吸引了来自 90 多个国家和地区约 45 万人参会。经过 12 年的发展，这一论坛已成为全球公认的文旅业界年度盛事及国际交流合作平台，提升了中国旅游外交话语权。何超琼说，澳门只是一个特区，但因为背靠祖国，她就有了信心并施展能力。下一个十年，论坛将迈向“文旅行业达沃斯”目标，向世界讲好中国文旅故事。' },
      { type: 'p', text: '作为大湾区综合文旅产业的领头人，何超琼对中华优秀传统文化进行了“生活化、艺术化、国际化”的解读和演绎，打造出具备长远发展效应的创新文化内容，助力澳门推动新质生产力发展。' },
      { type: 'p', text: '2010 年，美高梅引入“醒狮”这一传统年俗表演形式，打造“狮王争霸赛”年度体艺竞赛。选择醒狮，是因为她认为，醒狮是中华文化和精神的代表之一，“有华人的地方就有醒狮”，这是一种文化自信。值得一提的是，此赛事是世界三大南狮赛事中唯一设有女子组的比赛，展现了其包容性。今年赛事就吸引了全球多达 300万名观众线上线下观赛。' },
      { type: 'p', text: '今年，美高梅与国际知名导演张艺谋合作了《澳门 2049》驻场秀，融合青海民歌、蒙古呼麦、苗族歌舞、陕北说书、河北秧歌、彝族海菜腔、京剧、醒狮等非遗元素，并结合创新科技，将中华非遗文化转化为一场跨越语言与国界、大众化的演艺娱乐舞台表演，创新传播传承中华非遗文化。' },
      { type: 'p', text: '“同张艺谋导演的合作，我等了七年就是想给大家呈现最好的作品。”' },
      { type: 'h', text: '在文化之旅中，明确人生的意义' },
      { type: 'p', text: '何超琼对中华文化有一种深深的情结。她出生并成长在香港这座中西文化交汇并存的国际都市，对文化差异性更加包容。17 岁，她出国留学，主修商科的同时兼修了历史、艺术、国际关系。海外生活的经历，让她对中国文化理解得更加清晰和透彻，也更加明白了自己的来处及人生价值。' },
      { type: 'p', text: '回到 20 世纪 80 年代的香港，何超琼和很多年轻人一样困惑，不知自己的未来在何方。“好在我‘敢为人先’，也喜欢尝试新鲜事物。”当时香港经济正在腾飞，吸引了很多知名国际品牌入驻。何超琼瞄准机遇，创立品牌咨询顾问公司，帮助外国品牌将中华元素最大程度地融入产品和宣传中，让他们能够立足亚洲。' },
      { type: 'p', text: '“不知不觉间，我已经担当起守护和传承中华文化的角色。”她深深感悟到：推动中华文化“走出去”，原来首先要以尊重、包容的态度迎接外来文化，然后用对方听得懂的语言、能理解的角度去说服他们，共同去探索能让文化兼收并蓄的良方妙策，实践中国文化走出去的大营销观念。' },
      { type: 'p', text: '多个法国品牌的成功推广案例，让何超琼赢得法国文化部的肯定和信任。从那时起，她又承担起中法文化交流的使者之责。1993 年，何超琼加入香港法国五月艺术节董事会，至今担任主席。30 年间，带领艺术节为亚洲最大规模的法国文化活动之一。成功筹办多项中法文化交流盛事，促成多个中法顶级文化机构的深度合作。' },
      { type: 'h', text: '今年是中法建交 60 周年，何超琼格外忙碌。她先后促成了法国吉美博物馆与敦煌研究院签署协议，推动实现敦煌文化在全球范围内的数字化共享。见证法国吉美博物馆与四川博物馆签署合作备忘录，拓展文物保护与利用合作，推动中法文明交流互鉴。她还与北京恭王府博物馆深度合作，创造具有中国元素的文化外贸产品。' },
      { type: 'h', text: '“不以一己之利为利，而使天下受其利”，何超琼说：“当我切实地把自身发展与国家发展结合起来，把企业发展和社会进步结合起来，实现企业社会价值和个人价值的有机统一，就更有意义。”' },
      { type: 'h', text: '庆中轴线申遗，传递“文化自信”' },
      { type: 'p', text: '今年初夏的北京，何超琼身着绿色旗袍，站在古老的神仓建筑群中，和朝气蓬勃的孩子们一起，为中轴线拍摄宣传片。旗袍柔美的色泽和流畅的线条，将她与生俱来的高雅和秀外慧中的风采一展无余。当天，这组中轴线的“大片”即冲上热搜。' },
      { type: 'p', text: '1986 年，何超琼第一次来到北京。天坛、万里长城、北京故宫的“万道红墙、过亿黄瓦”给她留下了深刻印记。尤其当她知道了北京“中轴线”，认识到北京“中轴线”的建筑、空间、场所、立意是不可多得的物质和精神双重文化遗产后，她深深体会到中华民族的强大及中华文化的源远流长和博大精深，决心要让更多的人了解和热爱中华优秀传统文化。' },
      { type: 'p', text: '今年全国两会期间，何超琼提交了关于整体建设“宜居、宜游”中轴，打造中轴线国际新名片的提案，致力推动中轴线文化遗产资源的创造性转化和创新性发展。为此，她开展了一系列工作，助力北京中轴线申遗成功。一是联合国际著名指挥家、作曲家谭盾及多位中外艺术家，在原创的交响乐音乐会中加入古乐器、京剧等中国元素，于 4 月 6 日在中山公园音乐堂成功举办《中轴龙脉的钟声》音乐会，社会反响热烈。她还协调了中轴线上数个非遗点组织配合，为谭盾先生拍摄多个小型音乐会在非遗点上的快闪视频，在国际平台广泛传播。' },
      { type: 'p', text: '今年9月，何超琼联合北京和澳门多家单位，于澳门举办《一脉传“城”·盛世莲开》京澳双城影像展。展现了京澳两地民众在世遗建筑群中的美好生活，向世界提供文化遗产保护与可持续发展的中国案例，其中有数张参展照片被纳入《北京中轴线申遗保护工作成果展》。由澳门摄影师拍摄的青少年作品“喜跃中轴 青春筑梦”由北京市文物局指定为中轴线申遗成功的全市宣传画面。本次活动也激发了港澳同胞及国际友人对北京中轴线的浓厚兴趣，培养他们对中华传统文化的热爱，并向全球传递出中国的“文化自信”。' },
      { type: 'p', text: '“我穿的旗袍和布鞋就来自和中轴线素有渊源的国家和北京非遗老字号。希望‘国潮’走出国门，推动对外交流与传播。”' },
      { type: 'p', text: '文化是一个国家、一个民族的灵魂。文化兴则国运兴，文化强则民族强。习近平总书记指出，每一种文明都延续着一个国家和民族的精神血脉，既需要薪火相传、代代守护，更需要与时俱进、勇于创新。何超琼说：“我能为保护好祖国的文化遗产尽一份绵薄之力，何其有幸。”' },
      { type: 'h', text: '深耕大湾区，践行“大湾区人”使命' },
      { type: 'p', text: '《粤港澳大湾区发展规划纲要》出台以来，指引 9 个城市和 2 个特区融合发展、协同合作，港珠澳大桥进一步把香港、澳门、珠海连接在一起。深中通道、南沙大桥等通道的相继建成通车进一步完善了粤港澳大湾区快速交通网络,推动大湾区城市群进一步发展。如今，随着“一带一路”倡议、粤港澳大湾区建设等国家战略实施，大湾区把将近 8700 万人口的力量聚集起来。这些城市群已经基本形成“1 小时交通圈”，其生产总值占国民生产总值的三分之一，其经济总量约达 12.6万亿元人民币。“我现在天天的生活就是一个大湾区人的生活，一小时生活圈我现在是天天都在实现。”' },
      { type: 'p', text: '何超琼相信，要融合先要连接。以横琴粤澳深度合作区为例，一座莲花大桥把一水之隔的横琴和澳门接驳上。澳门的经验为横琴发展作模板，而横琴亦是澳门的发展后花园，为澳门经济适度多元发展提供支援。琴澳为大湾区的发展摸索出一条对接方程式，当中有许多制度创新、先行先试的举措。' },
      { type: 'p', text: '大湾区内有“一个国家、两种制度、三个关税区、三种货币”，粤港澳三地在法律体系、制度规则、管理理念到市场习惯都各有差异。琴澳协作，在过去几年汲取了不同的经验，才能将“制度之异”转为“制度之利”。' },
      { type: 'p', text: '今年也是横琴粤澳深度合作区成立 3 周年及第一阶段发展目标验收大考之年。何超琼表示，她将继续把深合区打造成具有中国特色、开创丰富“一国两制”成功实践的“横琴示范”，引领粤港澳全面合作向纵深推进，助力大湾区成为新发展格局的战略支点、高质量发展的示范地、中国式现代化的引领地。' },
      { type: 'h', text: '激发“她力量”，全国妇联常委的“新答卷”' },
      { type: 'p', text: '2023 年 3 月，在全国政协十四届一次会议“委员通道”上发言的何超琼掷地有声地说出“我是大湾区人”。这句话戳中了广大网友的心，让“大湾区人”这则词条迅速走红。何超琼庆幸地说，她之所以能担当起全国政协常委、全国妇联常委职责，首先得益于她 40 年前就开始学习普通话，她说这段经历为她打开了认识祖国的一道重要的门，帮助她增进人际沟通、了解传统文化，让她有了更多投入感和归属感。' },
      { type: 'p', text: '2003 年，何超琼当选北京市政协委员，2023年，她又当选为全国政协常委。履职过程中，她非常珍视自己被赋予的职责和使命，坚持发挥好身为港澳委员的双重作用。' },
      { type: 'p', text: '在最近一次香港区议会选举中，何超琼积极支持区议会选举，先后到多个街站支持爱国阵营的候选人。在近期举行的澳门特首选举中，她参选澳门第六任行政长官选举选委会，支持新一任行政长官选举顺利举行。这些经历让她更加深刻地认识到自己肩上的政治责任和历史使命，也让她更加坚定了为国家和民族利益不懈奋斗的理想信念。' },
      { type: 'p', text: '作为全国妇联常委，全国工商联女企业家商会副会长，香港各界妇女联合协进会（香港妇协）主席，何超琼一直积极发挥女性善于沟通的能力和姐妹间的团结力量，打破地域和语言隔阂，促进民心相通。' },
      { type: 'p', text: '何超琼带领的香港妇协，是香港最大、最具影响力，也是最国际化的妇女组织，每年都会出席联合国妇女地位委员会会议。她希望用好“一国两制”赋予香港高度国际化的优势，以更积极自信的姿态走向世界，作为反映香港真实情况的妇女声音，向世界展示“一国两制”的成功实践，以及港澳居民发自内心的人心归向。' },
      { type: 'p', text: '同时，香港妇协也在积极搭建中国和国际妇女交流合作的平台，做好民间外交工作，讲好中国故事。2019 年，何超琼带领香港妇协打造首届“巾帼建新力”国际妇女论坛，让世界各地的妇女领袖齐聚香港，就国际关注议题发出女性声音。连续三届把海外人士“引进来”，让他们亲身感受“一国两制”的行稳致远，并跟来自内地的代表直接交流互动。' },
      { type: 'p', text: '2023 年恰逢共建“一带一路”倡议提出十周年，何超琼在香港举办了“第三届亚非妇女论坛”，邀请了来自亚洲、非洲多国的妇女领袖和妇女代表。大家来到香港，就全球妇女关注的议题及推动各国妇女投入“一带一路”建设方面开展高层次交流。' },
      { type: 'p', text: '何超琼坦言，成为全国妇联常委后，她更有了一种时不我待、只争朝夕的紧迫感。粤港澳大湾区建设是国家重大发展战略，大湾区内有超过5000 万女性人口，区域内的“她力量”之强大可想而知。港澳姐妹应发挥自身在不同平台的资源优势，必须团结起来，交集“她网络”，发挥“她力量”，因地制宜、因才制宜为大湾区高质量发展增添创新动能。' },
    ],
  },
  {
    id: 'lu-yutong',
    kind: 'profile',
    date: 'Feb 28, 2024',
    read: 13,
    lang: 'zh',
    illus: 'assets/illustrations/portrait-gesture.svg',
    heroIllus: 'assets/illustrations/portrait-gesture.svg',
    title: '卢宇彤：逐梦"天河"，让中国超算领跑全球',
    titleEn: 'Lu Yutong · Tianhe and the race to supercomputing\'s frontier',
    dek: '中国第一位超算领军女科学家。她带领团队研发的"天河"系列超级计算机，让中国在全球超算领域站上巅峰。',
    tags: ["profile","超算","科学","天河"],
    body: [
      { type: 'p', text: '她长期致力于超算技术攻关，是五代银河、两代天河超算系统研制骨干，担任副总设计师的“天河二号”夺得世界超算500强六连冠，她以创新突破和奋勇拼搏亲历了中国超算从跟跑到领跑的跨越式发展，是当之无愧的“超算”女神。' },
      { type: 'h', text: '卢宇彤：逐梦“天河”，让中国超算领跑全球' },
      { type: 'p', text: '白大褂的领口和扣缝中，露出缀有碎花的连衣裙，一头乌黑垂顺的长发过肩，柳叶眉、大眼睛，卢宇彤是一位美丽优雅的科学家。但她从不愿意别人过度关注外在的“美”，而在意对她所做工作意义的理解。身为中国超级计算机（简称超算）崛起的见证者和参与者，她持续攻关国产超算技术，担任副总设计师的天河二号6次夺得世界超算500强冠军；她坚持应用为王，使广州超算成为全球用户最多、应用最广的超算中心之一；她还是国际超级计算大会（ISC）主席，是担任此职务的首位中国学者、世界首位女性科学家。' },
      { type: 'h', text: '协同“大脑”，中国超算飞速领跑' },
      { type: 'p', text: '由中国自主研发的超算天河二号看上去是一排排高大整齐的黑色机柜，里面装有32000颗主CPU和48000个协处理器，共300多万个计算核心。而卢宇彤和团队的任务是研发这个庞然大物的“大脑”，开发出一套极其精密复杂的软件管理系统，让如此之多的硬件在并行运转、协同工作时发挥出最大能效，从而成为计算速度最快的超级计算机。' },
      { type: 'p', text: '卢宇彤笑盈盈地描述自己“其实就是一个程序员”。她大部分时间是对着电脑敲击代码，日复一日为天河二号编写出一套有着层层叠叠并行网络的协同软件。让300多万个计算机核同时工作，并最大限度地保证它们各个并行不悖、又快且准地计算，其中难度之大，令人难以想象。但在卢宇彤的口中，很少能听到“难”字，她更愿意把如此高难度的软件设计描述成“巧妙”。“这个巧妙之处，在于要学会折中，要在各个功能运转的性能和能耗中找到一个平衡。所以我把代码设计过程叫做‘锱铢必较’，要尽力优化达到最佳临界值，既不能浪费也不能节省。”' },
      { type: 'p', text: '科学容不得半点马虎和懈怠，稍有错漏便会前功尽弃，那段时间，卢宇彤经常熬夜，三天三夜不合眼地连轴转，明明睡意渐浓，却得打起精神保持住十二分的清醒，异于常人的努力和毅力令许多男同事都难以企及。“大家说我是典型的处女座，对自己太狠，认定的事情，一定尽全力去拼到完美。”' },
      { type: 'p', text: '而这正是卢宇彤在长达一年的军训中练就的。保送国防科技大学读研的卢宇彤，在研一时穿起了军装坐着“大解放”来到了祖国的大西北。站军姿的她套在一层毛裤又一层棉裤中瑟瑟发抖；负重五公里越野跑的她在同伴的生拉硬拽中坚持完成任务；远距离射击的她匍匐在冻得僵硬的土地上努力瞄准……这个从未离开过南方城市的柔弱姑娘，觉得人生从此不再有战胜不了的困难。' },
      { type: 'p', text: '经过近三年的刻苦攻关，卢宇彤带领团队突破了系列关键技术，天河二号一经问世，超算的速度就领先了全球第二名2倍之多，连续六度称雄蝉联世界超算榜首，这标志着我国的超算事业从追赶到超越，跻身了世界一流，卢宇彤很庆幸能够参与和见证中国超算事业飞速发展的风雨历程。' },
      { type: 'h', text: '赋能生活，让超算“接地气”' },
      { type: 'p', text: '在天河二号初次斩获大奖时，社会上除了鲜花和掌声，也难免有些质疑，声称“天河”系列超级计算机耗电量大、闲置率高，甚至出现了要求相关技术研发“慢下来”的呼声。那段时间，卢宇彤和她的团队面对巨大压力。' },
      { type: 'p', text: '卢宇彤回忆道，“可能是因为在‘天河’之前，中国超算几乎没有什么宣传，也没有参与国际排名，大家觉得比较神秘。公众对超算并不了解，容易产生各种猜疑。”一天中午，卢宇彤边吃饭边思索该怎么办，最后她决定主动站出来发声，以自问自答的方式直接回应质疑。她一气呵成写下了《以“天河二号”为代表的中国超级计算机之吾问吾答（五问五答）》。随后，这篇语言严谨又不失幽默的超算科普文章，在网络上广为流传，质疑声渐渐消失。“我们可能太‘技术控’，如果我们学会交流、重视互动，让公众更多地了解超算，也许就会多些鼓励、少些拍砖吧。”' },
      { type: 'p', text: '这件事情让卢宇彤对超算发展有了新的思考和认识，“超算技术本身是科技创新的成果，但同时它也是支持其他领域科技创新的核心。再高深的科研，只有真正应用了，才能发挥更大的价值。”' },
      { type: 'p', text: '2016年，时任国防科技大学计算机学院软件所副所长的卢宇彤，举家从长沙迁移至广州，出任国家超级计算广州中心主任，她将重心由超算系统研制转到超算应用，坚持“应用”与“研发”并举。' },
      { type: 'p', text: '超算应用涉及领域极广，需要不断学习交叉学科的新知识，还需要花大量时间做穿针引线的沟通工作。卢宇彤笑着说，“我永远对一切事物充满好奇，刚开始压力确实挺大，但学习使人快乐。”' },
      { type: 'p', text: '卢宇彤带领团队自主研发了一站式融合超算应用平台，让天河二号在各个行业不断拓展应用边界，让庞然大物接上了“地气”。“比如汽车安全碰撞分析，以往的研究方式可能需要几百台真车进行实验，现在通过建立数字模型，借助超级计算机，就可以通过数字样车实现数据收集，再通过真车碰撞实验进行核实，最后用几台车就可以完成，而且实验时间从几个月缩短到几天。”' },
      { type: 'p', text: '而当疫情来临，她又带领团队开发了新型冠状病毒肺炎CT影像智能诊断平台，平均15秒就可完成一个病人的CT图像智能诊断。还紧急启动了相关疫情追踪软件的研发工作，实现了每5-10分钟完成一次用户的轨迹数据采集，协助政府进行精准防控。' },
      { type: 'p', text: '如今，广州超算成为全球用户最多、应用最广的超算中心之一，位列“世界最具应用影响力超算中心”前五，也是唯一不需政府运营补贴的国家级超算中心。卢宇彤说：“中国的超算应用需求旺盛，一方面带动中国超算系统的演进，另一方面将推动中国各行业领域的创新发展。”' },
      { type: 'h', text: '超算史上，第一个女性发声者' },
      { type: 'p', text: '在德国法兰克福召开的国际超级计算大会（ISC）2017 开幕式上，卢宇彤当选大会会士（ ISC Fellow），成为中国首位获此殊荣的学者，更是全球唯一获此殊荣的女性。2019年，卢宇彤出任国际超算大会（ISC）主席，大会成立40多年迎来首位女性主席。' },
      { type: 'p', text: '卢宇彤常对学生说，“要想赢世界，要先看世界。”要知道研究领域的世界前沿，了解它遵循的规则。“我可能是最早一批互联网用户”，90年代初，卢宇彤在UNIX系统界面的台式机上靠敲击字符联上网络，查阅国外计算机领域的前沿信息，也会请在国外深造的同事带回英文文献学习。“我觉得只要你有心，无论在哪里、出不出国，都可以想办法了解世界，拓展国际视野。”' },
      { type: 'p', text: '国际化的视野让卢宇彤在担任大会会士和主席期间，很快融入世界超算的大家庭。她用“懂原则、守规则”树立大国形象，不遗余力地创造交流机会，把中国学者推向世界。“以前超算领域的国际合作很少，当年美国和日本不愿意和我们交流。现在不可同日而语了，有实力就有话语权，中国超算经过几十年积累，终于可以在国际学术圈发出自己的声音。”在她的带动下，整个亚洲区域的国家也跟着活跃起来。' },
      { type: 'p', text: '“天河二号”蝉联冠军后，美国毫无征兆地发起制裁，禁运前往中国的因特尔处理器，这意味着我国各个超算中心都要换成自主研发的处理器，相当于对天河二号做一个“心脏移植”大手术，术后还能否一如既往地“快”都是未知。一时间，世界各国都在冷眼旁观。' },
      { type: 'p', text: '制裁发生后，卢宇彤怀着复杂的心情在“劲敌”瞩目下做大会发言。她回想起前辈们、自己和团队一路走来，奋勇拼搏、自主创新，中国超算从无到有、从弱到强的奋斗历程，感慨万千。站在聚光灯下的她，底气十足，淡定而坚定地说：“……无论发生什么，明天永远值得期待！”会场响起雷鸣般的掌声。' },
      { type: 'h', text: '从小播下“科研种子”，受益一生' },
      { type: 'p', text: '在卢宇彤心中，母亲是位优秀女性。在那个年代母亲就读了研究生，对自己要求之高可见一斑。母亲是大学老师，辛勤拉扯着四个孩子。可母亲把家里打理得井井有条，生活少有“一地鸡毛”，“超算的关键‘协同管理’思维和技能，可能就是从母亲那里偷师学来。”卢宇彤打趣说。' },
      { type: 'p', text: '而说起父亲，她的脑海中永远是那个在台灯下读书的背影。同为大学老师的父亲，从不因她是女孩而在教育上设限，大部分孩子在攻关学校课程时，她被《十万个为什么》和《小灵通漫游未来》等课外书深深吸引，父亲不加阻拦，总是在一旁笑盈盈地看着。当年才10岁的卢宇彤想去寄宿制的湖南师大附中读书，母亲说什么都不同意，可她不“听话”，逼得母亲只好给出差的父亲打电话，“我爸就说‘你让她去’！”回忆起这件事，卢宇彤至今都充满感激。' },
      { type: 'p', text: '用卢宇彤的话说，在湖南师大附中的六年改变了她的人生。在高考压力下，学校依旧设立图书馆及阅读课，卢宇彤继续沉浸在书的海洋，学校自由的学风更让她在英语角、球场、文艺活动、学农、学工等各个方面，满足了好奇心。高中时期，卢宇彤参观了“银河一号”，她立马被这个体积庞大、插满电线的超级计算机所吸引，从此，与超算结下了一世之缘。' },
      { type: 'p', text: '“计算机是当时最潮的专业，我报大学志愿时毫不犹豫地就选了。”数学拔尖的卢宇彤以优异成绩考入国防科技大学计算机系，出色的科研能力使她大四毕业设计前，就进入了教师课题组，为银河二号编译器的开发做验证。研究生毕业以后，她投身银河事业，连续完成两个重要型号的国产超算系统。这时，英语流利的卢宇彤有了去世界顶尖学府深造的机会，经过一关关考试、选拔，她拿到了国家留学基金委的出国留学名额和奖学金。就在此时，国家打造“新型深度并行银河系统”的号角吹响，在“小我”和“大局”之间，她毅然放弃了出国深造的机会，继续留在“银河”战队。此后，从硕士到博士，从“银河”到“天河”，卢宇彤随同“超算”国家队一起飞跃成长。' },
      { type: 'p', text: '“父母对我的信任，给予我自信和自由，让我找到了真正喜爱的学科和事业，受益终生。”如今在对待儿子的教育上，她传承“要相信孩子”的理念，“热爱和坚持，才有赢在人生的入场券。”' },
      { type: 'p', text: '谈及未来，卢宇彤踌躇满志，“在未来相当长时间内，超算仍将是唯一的高端计算平台，是世界各国激烈竞争的重点领域，国产超算应用发展任重而道远，机遇与挑战并存。我们要牢记习近平总书记加快建设科技强国，实现高水平科技自立自强的嘱托，不断创新超越，让中国超算更快、更强、更好。”' },
    ],
  },
  {
    id: 'ye-qiaobo',
    kind: 'profile',
    date: 'Jan 8, 2022',
    read: 11,
    lang: 'zh',
    illus: 'assets/illustrations/woman-reading.svg',
    heroIllus: 'assets/illustrations/woman-reading.svg',
    title: '叶乔波：回眸冬奥40年，巾帼从未让须眉',
    titleEn: 'Ye Qiaobo · Forty Olympic winters — women never behind',
    dek: '40年前的阿尔贝维尔，她在脑海中一遍遍"回放"自己的速滑。40年后回望，她说：中国冰雪的零的突破，几乎都是女将们实现的。',
    tags: ["profile","冬奥","速滑","体育"],
    body: [
      { type: 'p', text: '距离冬奥会不到一个月，冬奥运动健儿正在做着最后的冲刺。40年前，同样是在冬奥会前，一个叫叶乔波的女运动员在脑海中不停的做速滑“电影回放”，闭着眼睛，用心去感知自己每一秒的速度，将动作的每一个细节，在“大脑屏幕”里过上一遍。果然，她不负众望，在几天后的法国阿尔贝维尔第16届冬奥会上“平地一声雷”，在对手严重犯规、裁判不予公平裁决的情况下，获得女子500米、1000米速滑两个亚军，为中国代表团第一次获得了冬奥会历史上的奖牌，实现了中国冬季项目奖牌“零的突破”。' },
      { type: 'h', text: '打破“两个第一”，红颜更胜儿郎' },
      { type: 'p', text: '叶乔波回忆，80年代初期，中国代表团刚下飞机，就看到了嘲讽中国队的“两个第一”标语：“中国队第一次参赛” “中国队倒数第一”。那个时候她和队员们什么都不想，就想拼尽全力赛出好成绩，摘掉这个对祖国歧视与挑衅的标签。自1980年中国首次参赛冬奥会，经过12年的努力，中国代表团彻底打破了“两个第一”的魔咒。从1992年叶乔波获2枚银牌，实现冬奥会奖牌“零的突破”开始，接下来的每一届冬奥会，中国冰雪项目都斩获新的突破。1994年，陈璐获得花样滑冰女单季军，斩获该项目中国队首枚奖牌；1998年，徐囡囡获得女子自由式滑雪空中技巧季军，实现中国冬奥会雪上项目奖牌“零的突破”；2002年，女子短道速滑运动员杨扬取得了中国冬奥会历史上首枚金牌；2010年，女子冰壶斩获该项目中国队首枚奖牌。那一年，中国代表队共获5枚金牌，除一枚双人花样滑冰首金，其余四枚皆被女子短道速滑各项比赛包揽，国家排名首次进入前8，创下了史上最好成绩。截至2018年韩国平昌冬奥会，中国共组队参加了11届冬季奥运会，获得13金、28银、21铜，共62枚奖牌，其中有40枚是冰雪女将们拼下来的。' },
      { type: 'p', text: '叶乔波笑着说，“不知道这是偶然还是必然，我国冰雪运动在冬奥会上很多‘零’的突破都是女运动员们实现的，连教练都不得不服气，夸我们‘红颜更胜儿郎’。”' },
      { type: 'p', text: '为何“巾帼如此的不让须眉”？叶乔波不加思索的说，去年是中国共产党成立100周年，回顾过去的百年，正是因为党和国家高度重视妇女解放，把男女平等立为国策，致使中国妇女地位由“小脚女人”跨越到“妇女能顶半边天”，而女性在体育竞技舞台中的地位也随之发生了变化。“我恰好身处新中国妇女发展的红利期，不用再忍受老一辈女性在旧社会中受到的阶级压迫和性别压迫，更有机会去和男性一样凭借自己的本事拼搏，这种反差无形中赋予了我很多力量，同时我骨子里又继承了女性文化中的吃苦耐劳和坚韧顽强的传统，训练时，教练让做3分钟蹲腿，我一定做5分钟，做任何训练计划，都要求自己比别人多一点，形成了一种惯性。所以我感觉很多女运动员都热爱自己从事的项目，非常珍惜能为国出战的机会，敢于对自己更严苛，把自己身体里潜在的力量毫无保留的激发出来，所以才铸就了如此的辉煌。”' },
      { type: 'p', text: '同时，党和政府坚持贯彻男女平等的宪法基本原则，无论男女，只要能让五星红旗在奥运赛场上升起，都可享受同等的奖励，并给予前所未有的高度评价和荣誉，唱响了 “乔波精神”“女排精神”等弘扬民族精神和女性力量的时代主旋律，树立了叶乔波、郎平等优秀典型，以此激励更多女性投身于竞技体育运动。叶乔波用的就是这份回报，让因哥哥不幸残疾而常常黯然神伤的父母和家人再次看到了生活美好的一面，坚定了好好生活、享受生活的希望。' },
      { type: 'h', text: '中国冰雪蓄势待发，女性力量势不可挡' },
      { type: 'p', text: '冬奥会自1924年举办，已发展了近百年，现已成为世界上规模最大的综合性冰雪项目运动会。比起欧美地区的先天优势，我国受气候、地理、经济条件等因素的影响，冬季项目开展时间较短，起步较晚，基础相对薄弱。改革开放后，冰雪项目踏上了飞速发展的轨道。1984年10月，中共中央下发《关于进一步发展体育运动的通知》，充分肯定了体育在振奋民族精神方面发挥的突出作用，强调要采取有力措施，使体育运动不断向新的广度和高度发展，争取在本世纪内建成体育强国。叶乔波正是赶上了这个好时候。' },
      { type: 'p', text: '回想起自己训练的艰苦岁月，叶乔波下意识的攥紧拳头，脸色显得格外凝重。因为没有室内冰场，教练只能带着她们去找野冰滑，哪里冷就往哪里去，常常在零下30多度的凛冽寒风中背着行囊一路向北。叶乔波说，“那种冷是刻骨铭心的”。即便如此，她和队友们也从不叫苦叫累，因为她们深知，党和国家已经最大限度的给予照顾和关怀。“那个时候大家都吃粗粮，我们在体校吃的是细粮。很多人家吃不上肉，我们在体校是有肉吃的。”叶乔波说，所有人心中只有一个信念——报效祖国、为国争光。冲出亚洲，走向世界！' },
      { type: 'p', text: '20世纪90年代，中国经济快速发展，国家体委相应制订和实施了《奥运争光计划》。2000年，北京成功申请为2008年奥运会主办城市，一时间举国欢腾，体育之春潮遍及中华。2015年，2022年北京冬奥会申办成功，北京成为历史上第一个“双奥之城”，竞技体育再一次迎来历史性的发展机遇，特别是冬季体育项目遍地开花。如今我国的滑雪场已达 703 个，室内冰场250 个，滑雪人口 1570 万。叶乔波无比羡慕、自豪地说，“现在的室内冰场条件都特别好，和我们那会确实是没法比，运动员人才储备也比以前多了，训练的技术也上来了，还有科技的红利，可以说冰雪项目能取得今天的成绩，这40年的追赶速度是相当惊人的，接下来就是蓄势待发！”' },
      { type: 'p', text: '此次北京冬奥会将包括51个男子项目和46个女子项目，另有12个混合项目，男、女运动员人数分别达到1578人和1314人，女性运动员占比为45.44%，是历史上女性参赛最多的一届冬奥会。为了提高冬奥会中女性运动员参赛数量，北京冬奥会新增了女子单人雪车、自由式滑雪男女子大跳台等7个小项，共产生109枚金牌。' },
      { type: 'p', text: '“女性运动员的参赛比例进一步提高，参赛运动员的男女比例更趋于平衡，这成为北京冬奥会的一大亮点，体现了《奥林匹克宪章》中‘男女运动员均应得到平等对待’的精神。”叶乔波特别补充了一个细节：延续了近1200年的古代奥运会，一直只允许男性参加，女性不仅没有参赛资格，甚至没有观看的权利。直到1900年的第二届现代奥运会，才允许女性参赛，当届只有19名女运动员。“北京冬奥会迈出的‘一小步’必将是女性与冬奥历史上的‘一大步’，女性的力量已经势不可挡。”' },
      { type: 'h', text: '以运动员为中心，以家庭为中心' },
      { type: 'p', text: '作为北京冬奥组委运动员委员会委员，叶乔波为了不让后人再吃她当年的苦，她把自己过往运动生涯中的宝贵经验总结凝练，就场馆建设、竞赛组织、运动员服务等众多方面，为冬奥组委运动员委员会提出了十几条富有建设性和针对性的意见建议。比如，对运动员的餐饮食物成分做出清晰准确的标注，防止小概率过敏事件的发生；尊重世界各国不同种族的信仰和饮食习惯，提供多种就餐选择；运动员休息室有直梯抵达，与卫生间、淋浴室位置动线合理，节省运动员体力和时间，储物柜带锁，保护参赛装备，让运动员得到真正安心、放松的休息。叶乔波表示，“运动员是奥运会的主角，北京冬奥会一个很重要的工作理念就是‘以运动员为中心’，本着这样的理念，我们这些老运动员为北京冬奥会没少出主意，比如倡议建立一个运动员与摄影记者图片共享平台，让远动员输入自己的名字就可以找到和保存自己参赛时的‘高光时刻’；甚至对领奖台等待区域都提出换成木凳和提供暖宝宝的建议，大家肯定想不到，运动员等待上台领奖的时候一般都冻僵了。”' },
      { type: 'p', text: '身为一名女性，她凭借细腻独到的观察和见解，还提出了要“以家庭为中心”的建议：允许运动员携家人一起参赛，提供家庭门票和住宿安排，上领奖台时能抱着孩子一起合影留念等等，要体现对运动员和家人更多的人文关怀，以此保障运动员更加平稳和积极的心理状态。叶乔波解释说，“我们那个年代比赛更多的是拼体能拼毅力，现在随着科技在竞技体育中的应用，运动员比拼的更多是综合素质，反而利于有一定阅历的运动员出成绩，再加上运动医学的发展和科学训练，运动员们的运动生命在逐渐延长。所以，现在奥运会中涌现了很多‘妈妈运动员’，我们要为这些妈妈们考虑周到，尽可能让她们能兼顾比赛和家庭，让好心情、好心态加持，赛出自己的好成绩。”或许因为疫情的复杂变化，这个建议一时难以实现，但关怀家庭的人文精神却让人眼前一亮，不禁为她女性独特的见解叹服。' },
      { type: 'p', text: '时间回到1994年3月16日，在首都机场候机厅鼎沸的欢呼声中，背着冰刀出征的叶乔波坐着轮椅凯旋，外国专家手术中不停的摇头，从她的膝盖中前后共取出13块指甲大小的碎骨，惊叹她非人般的坚毅。如今，她用伤痛浇铸“破零”丰碑的悲壮已成往事，但她强忍伤病之躯勇夺奖牌的“乔波精神”却流淌在一代又一代冰雪女运动员们的血液中，激励她们创造一个又一个“零”的突破，让自己变得“更快、更高、更强”。正如叶乔波所言，“巾帼不让须眉”仿佛已经镌刻到冰雪女将们的基因里，2022年北京冬奥会，她们一定还会大放异彩，再创辉煌！' },
    ],
  },
  {
    id: 'cao-qizhen',
    kind: 'profile',
    date: 'Dec 15, 2023',
    read: 15,
    lang: 'zh',
    illus: 'assets/illustrations/portrait-contour-1.svg',
    heroIllus: 'assets/illustrations/portrait-contour-1.svg',
    title: '曹其真：斯世多伪，吾曹其真',
    titleEn: 'Susana Chou · The world is full of falseness — mine is truth',
    dek: '她出身豪门，征战商场；澳门回归后从商转政，担任特区立法会主席十年。退休后第二天，她又踏入另一间办公室——开启"从善"20年。',
    tags: ["profile","澳门","政治","慈善"],
    body: [
      { type: 'p', text: '“斯世多伪，吾曹其真”，在曹其真办公室的墙上，这幅字帖已伴她多年。当年澳门回归，她当选为特别行政区首届立法会主席，93岁的澳门老书法家梁披云为她题写下这八个大字。无论早年间在商场中打拼，还是之后在政坛上立业，曹其真都以直言、敢言、敢议、善议的一股“真”劲儿，书写出独特的传奇人生。' },
      { type: 'p', text: '伴随记者的提问，曹其真的目光时而明快时而凝视，她脑海中的时针转动起来了……' },
      { type: 'h', text: '真敢，驰骋商场凭魄力' },
      { type: 'p', text: '55年前，不到30岁的曹其真从法国巴黎学习归来。父亲安排她到澳门协管家族产业之一 —— 澳门针织有限公司。不同于父兄在香港太子大厦里舒适、敞亮的办公室， 针织公司坐落在居住拥挤、店铺局促的噶地利亚小街上一栋破旧的三层楼房里。办公室在一楼，二楼和三楼便是工厂厂房，简陋的环境让曹其真感到十分沮丧，恨不能脚一跺地就回到巴黎。只是连她自己也没有想到，她不仅留了下来，还在三个月内当上了这家公司的经理。' },
      { type: 'p', text: '“父亲把澳门这家公司交给了我，但给我的是一家面临倒闭的公司。”曹其真回忆说，当时的总会计师把亏本当作盈利算，所以父亲不断地扩充公司，等到她接手时，针织有限公司已有多间针织厂，并有超过1000名员工的规模。但当时公司无论在管理方面还是资金周转方面都存在严重的问题。得知真相后，父亲先是想办法注资渡过难关，同时在欧洲为曹其真拉来一个棘手的“大订单”。为了公司和自己能在澳门生存，曹其真必须将单子接下并按时交货。“我下决心立刻整顿公司，但说实话，我当时心中一点头绪都没有，根本不知道应该从什么地方着手。”接下来，曹其真每天到各间工厂打转，仔细具体地观察每一个车间的运作情况。' },
      { type: 'p', text: '经过调研，她发现公司里有一伙嚣张跋扈、谁都不敢惹的毛头小子，他们聚集的地方被称为“红灯区”，连曹其真自己进去考察也害怕被打。但为了公司的生存，她决定杀一儆百，先从最典型的“红灯区”着手。她先说服老师傅和工人代表同意改革，行不通后只好来硬的——裁员。' },
      { type: 'p', text: '“那天晚上，我在家里用毛笔写了一张告示——《告澳门针织厂全体员工》……”这是曹其真一生中写下的唯一一张告示，也是最令她难忘的一件往事。告示上写着：为整顿厂风，从即日起，榜上有名者不准进入工厂。第二天一早，曹其真来到工厂门口，把告示贴在工厂外墙上，她独自站在只能让一个人经过的厂门外，等待工人们的到来。' },
      { type: 'p', text: '很快，上班时间到了，曹其真让榜上无名的员工一个一个地进入大门，待工厂的开工钟声一响，就吩咐把大铁门关上，不再让任何人出入。门外聚集着30多个“榜上有名”的小青年，大声吆喝鼓噪，威胁说要冲进工厂大门……“当时的我就一直站在大口，我告诉他们，要冲就从我身上踩过去，今天除非我死，谁也别想再进工厂。”不到30岁的曹其真，在玉软花柔的年纪，目光如炬地站立在工厂门口，她不是不怕，但她知道，成败与否，在此一搏。' },
      { type: 'p', text: '僵持半小时后，小青年们的情绪逐渐平复。曹其真诚恳地说，既然她贴了告示，是不会让他们再进工厂的，但如果他们想，可以随时到她的办公室好好谈谈。之后，在曹其真的帮助下，这些调皮捣蛋的小青年变成了一支“编外军”，在订单旺季发挥了冲锋陷阵的作用。就这样，曹其真跨出了整顿公司的第一步。从此，公司的面貌彻底转变，顺利地完成了所有订单，让公司在澳门站稳了脚。' },
      { type: 'p', text: '“每每回想起这件事情，我都深深地感到自豪。我的体会是天下只有想不到的事，没有做不到的事。办法必须要靠我们自己想，而路也要靠我们自己走。只要努力，我们的命运是掌握在自己手上的。”' },
      { type: 'h', text: '真干，心怀大我咤政坛' },
      { type: 'p', text: '位于澳门南湾湖填海区十三号地段,有一栋外形呈三角形,顶部有一个竖立圆筒形的建筑，这便是曹其真曾倾力十载的立法会大楼。1999年10月12日，曹其真当选为澳门特区第一届立法会主席，她辞去其他社会职务，彻底退出家族生意，全身心投入到首届政府的立法工作。' },
      { type: 'p', text: '“请讲中文的议员，跟我用普通话宣誓……”曹其真带领第一届立法会议员面向国旗、区旗庄严宣誓。“从这个黎明开始，我们澳门的立法会开始使用中文进行讨论。作为中国人，用中文主持立法会会议，我感到荣耀。”时隔多年，曹其真仍能清晰地回忆起当时心潮澎湃的感觉。' },
      { type: 'p', text: '其实，早在1976年，澳门有史以来第一届立法会成立时，曹其真便进入立法会，成为当时唯一的女议员。那是澳葡时期的立法会，以葡萄牙语为官方语言，很多法律文本没有中文译本，即便有也是错误百出。曹其真回忆道，有一年施政方针辩论时，她发现其中有一段话提到了澳门的糖果厂，她顿生诧异，从未听说过澳门有糖果厂啊？为探明究竟，她对照中葡文本，才发现原来是翻译把“制衣厂”译成了“糖果厂”。“因为在葡语中，‘制衣’和‘糖果’这两个字是非常接近的，这样的事例听来有些可笑，但实际上类似这样的错误在那个年代不足为奇。”' },
      { type: 'p', text: '曹其真说，当自己被选为特别行政区立法会主席那一刻起，她的心中就在不断地琢磨，作为中华人民共和国的澳门特别行政区立法会主席，她不能再任由这种情况继续下去，因此她为自己定下的首要任务就是在保证葡文立法水平不降低的情况下，要保证由立法会有通用的中文法律文本。' },
      { type: 'p', text: '“当然这对我来说，是一个极具挑战性且难度非常大的工作，因为第一，我不是读法律出身；第二，我的葡语并没有受过正规的训练，虽然用葡文与人交流还算可以，但如果说要真正深入理解，用葡语书写法律条文还是有很大难度的；第三，我几乎从大学毕业后就没有用中文写过任何文章，就更不用说是用中文写法律条文或编写立法会委员会的意见书了。”但是，为了祖国和人民的尊严，曹其真暗自立誓，即使难度再大，她也必须在任期内尽量把这项工作做好。' },
      { type: 'p', text: '这项看似简单的工作，需要曹其真和她的团队有过人的语言能力、充足的法律经验储备，以及在当时极为难得的国际视野。功夫不负有心人，在她的带领下，团队最终在极短的时间内完成编译工作，为澳门中文立法工作打下了扎实的基础。' },
      { type: 'p', text: '也许是因为曹其真身上总有一股让人难以抗拒的力量，就像当年，年纪轻轻的她站在工厂门口，却无人敢跃她而过。在她执掌澳门立法会的十年中，彻底改变了回归前低效的工作面貌。在没有增加人手的情况下，克服了种种困难，十年中制订了141部法律，包括《劳动关系法》《科学技术纲要法》《个人资料保护法》《预防及遏制清洗黑钱犯罪》等，为日后澳门经济社会的快速发展打下了法制基础。' },
      { type: 'p', text: '2009年2月25日，《维护国家安全法》在特区立法会全体会议上高票通过，并于次日生效，标志着澳门在维护国家安全方面迈出了重要一步。“‘一国两制’下的澳门，是中国的澳门，我们有责任维护国家安全。”之后，担任了三届立法会主席的曹其真选择离任。离任次日，68岁的她开启了新的职业生涯……' },
      { type: 'h', text: '真感，悟道大爱献公益' },
      { type: 'p', text: '2006年，曹其真生了一场大病，她深刻体会到生命的脆弱，“身体健康和精神愉快比权和钱都重要”，也进一步领悟到佛家所说的“用有”比“拥有”要重要和实际。病愈之后，她下决心争取在自己剩余的岁月里，用健康时的每一分每一秒去做她一直想做，却还未来得及做的事情——慈善。' },
      { type: 'p', text: '曹其真请好友林金城帮忙创办澳门同济慈善会，她先把十年的立法会主席的薪金预支投入慈善会，并请好友代为主持慈善会的工作。2009年10月16日，曹其真卸职的第二天便投入到慈善会的工作。从立法会主席的办公室走到慈善会主席的办公室，短短的一段路程，曹其真等了许久。可真正开始做慈善，她才体会到，原来把自己辛苦赚来的钱妥善地花在有益社会、真正帮助到有需要的人身上，并不是一件容易的事情。' },
      { type: 'p', text: '“我觉得要合理、正确地花钱，真的可能比正当赚钱更加困难。”曹其真感受到 ，在慈善事业中，被资助或帮助的团体和个人都是急需救助的弱势群体，对他们作出的每一个承诺，都是一份沉甸甸的责任，如果不兑现，只会加重这个群体的弱势，甚至还可能造成恶果。因此，曹其真在“从善”的过程中，反而比从商和从政时更加战战兢兢，更加怕犯错误。“因为我知道我犯的任何一个错误，都可能导致很多人遭受痛苦和损害”。' },
      { type: 'p', text: '曹其真一向认为“教育”才是最高境界的慈善。十年立法会工作使她对澳门缺乏中葡双语法律人才有深刻的认识，同时考虑到澳门承担了中央赋予打造“中国与葡语系国家商贸合作服务平台”的任务，她决心为推动这项工作贡献一点力量。 “中葡法律双语人才计划”便成为同济慈善会的第一个重点项目。曹其真对这个项目投入共同不止是资金，还有对参与项目的青年学生多年倾注的真诚无私的关爱和殷切的期望。只要有时间，就飞往里斯本看望在那里学习的澳门学生，与他们分享自己的奋斗经历和人生经验，告诫他们要牢牢记住自己是中国人，要努力学习，要为国为民争光。' },
      { type: 'p', text: '2013年，澳门同济慈善会在北京成立办事处，曹其真将资助的目光投向更偏远的中西部地区。“在亲自做慈善的过程中，我认识到，其实在贫穷和落后地区不要说几百万人民币是天文数字，就算几十万人民币也是可以做很多很多的事情。”于是一个名叫“新一千零一夜”的项目进入澳门同济慈善会的视野。这个项目主要以关爱农村住校生群体为主，针对“睡前15分钟”这一学校管理痛点，设计了“乡镇学校住校学生睡前故事干预项目”，每天为在住校生在睡前广播15分钟的故事。' },
      { type: 'p', text: '“当我首次听到这个项目时，心里对项目的成效存在很大的疑问，但令我想不到的是，最终效果远远地超过我的预期。”曹其真说，由于这些乡镇学校的学生都是留守儿童，他们中绝大部分人从小就没有父母在身边，当然也从来没有经历过父母在他们睡前讲故事，让他们自然地、安静地进入梦乡的场景。而“新一千零一夜”中的故事既有趣温馨又有教育意义，在陪伴孩子们好眠的同时，还能帮助解决孩子睡前互相打扰，入睡困难的问题，更有助于消解学生知识视野狭窄，普通话不标准等困扰。两年内，项目便覆盖16个省市56区县的336所农村寄宿制学校，超过7万名孩子每天都能在有爱有温暖的睡前故事中进入梦乡。' },
      { type: 'p', text: '“这个项目令我再一次明白，我们只要肯从最平凡的小事情做起，然后再去其他的县城和乡镇推广，那就会变成一件意义非凡、一件了不起的大事情”，曹其真因此坚定了“从小事做起”的想法。她再次认识到，做慈善是否有真正的效果，并不取决于善款的多与少，而是取决于项目设计人是否真正用大爱之心投入其中。' },
      { type: 'p', text: '十年过去，慈善会的一件件“小事”正在慢慢变成“大事”。17个学前教育项目，21个基础教育项目，5个其他教育及8个推动公益行业发展的研究……项目执行地点从澳门到北京，从北京到西北腹地，再到全国各地……“我并没有伟大的理想，但我要尽自己所能去帮助我能够帮助的人。”' },
      { type: 'p', text: '自1968年进入澳门针织有限公司开始从商；1989年参与起草基本法工作开始从政；2009年全力投入慈善事业。从商人到政客到慈善家，曹其真的人生是这样规划的，也是这样进行的。无论在哪个领域，她都干得风生水起，成为业界叱咤风云的人物。' },
      { type: 'p', text: '“其实我的人生中，不断遇到挫折和困难的事情。但我也真的是很幸运，每一次都会顺利地渡过难关。”曹其真说，“人生中总会有不如意的事情发生，遇到困难的时候，要坚强地想方设法去解决困难，从困境中冲出来。在解决困难的过程中，学到很多书本上没有教给我们的知识和为人处世的道理”。' },
      { type: 'p', text: '这位大半生都在拚搏和忙碌中度过的老人，没有肆意享受悠闲富裕的晚年生活，她选择了“退而不休”，为了继续追逐自己的梦想——世界变得越来越美好。更期待着能够完美地完成自己20年从商、20年从政、20年从善的人生目标。' },
    ],
  },
  {
    id: 'yang-lan',
    kind: 'profile',
    date: 'Sep 1, 2025',
    read: 13,
    lang: 'zh',
    illus: 'assets/illustrations/portrait-contour-2.svg',
    heroIllus: 'assets/illustrations/portrait-contour-2.svg',
    title: '杨澜：北京+30，世妇会打开的那扇窗',
    titleEn: 'Yang Lan · Beijing +30 — the view the WCW opened',
    dek: '三十年前的世妇会，让世界看到中国，也让她看到了一个更大的自己。三十年后，她仍在同一扇窗前。',
    tags: ["profile","媒体","女性力量","世妇会"],
    body: [
      { type: 'p', text: '1995年，27岁的杨澜站在北京人民大会堂的舞台中央。那一年，北京迎来世界的目光，第四次世界妇女大会拉开帷幕。当她说出一句再简单不过的问候——“Here we are in Beijing”。顷刻间，全场爆发出雷鸣般的掌声，那掌声冲破语言和文化的藩篱，也敲开了每一位女性内心的一扇门。' },
      { type: 'h', text: '杨澜：世妇会点亮的视野，从未停步' },
      { type: 'h', text: '文/ 本刊记者 王梓蓉' },
      { type: 'p', text: '1995年9月，杨澜匆匆从美国哥伦比亚大学新闻学院请假归国，与央视主持人倪萍并肩走上第四次世界妇女大会开幕式的舞台。来自世界180多个国家和地区的代表，穿着各具特色的服饰，齐聚一堂。有人头戴色彩斑斓的非洲头巾，有人披着轻盈的南亚纱丽，也有人身着简洁利落的西式套装。灯光炽烈，镜头聚焦，掌声如潮，那不是客套的礼仪，而是一种由衷的回应，一种因同处历史节点而产生的共鸣。' },
      { type: 'p', text: '“那一刻，你真的感受到女性的凝聚力和热情。”多年后，杨澜仍记得当时的震动，“全场的回应让我热泪盈眶，也让我第一次真切意识到，作为女性，我们团结的力量如此伟大。”' },
      { type: 'h', text: '女性本来就值得尊重' },
      { type: 'p', text: '与此前主持过的各种大型晚会不同，95世妇会是一次真正“改变世界”的大会。不同肤色、不同语言的女性在一起，谈论的不是娱乐与表演，而是命运与未来。杨澜说：“作为女性，能够在自己国家的主场见证这样一场盛会，心中由衷地感到骄傲。”很多年后，在世界各地与女性领导者重逢，她常常听到一句问候：“当时你也在1995年的北京吗？”那场大会成为某种“精神护照”，把她与世界各地的女性连接在一起。' },
      { type: 'p', text: '杨澜说，自己在世妇会现场经历了一次“观念的巨变”。她坦言，在此之前，虽有一定性别意识，但仍深受社会普遍观念影响。“我过去一直觉得，女性要变得有能力、很强大，才会被看见和尊重。”' },
      { type: 'p', text: '这种观念，在她进入电视行业时便能窥见。1990年，杨澜还是一名北京外国语大学的学生，参加央视《正大综艺》节目主持人选拔。当制片人说要找“清纯乖巧”的女主持人时，她当场质疑：“为什么电视上的女性，总是作为附属和助手的存在？为什么不能有更多有知识、有观点的女性？”凭着这份“初生牛犊不怕虎”，她得到了关注和机会。但在世妇会的会场上，面对来自世界各地的姐妹，她第一次真切体会到，“有一些地方的女性不能独自出门，有的没有财产继承权，有的甚至会遭受私刑或虐待。看到她们的处境，你会由衷地呼喊：我们不是因为变得强大才值得尊重，而是因为我们本来就该被平等对待。”' },
      { type: 'p', text: '留学归来后，杨澜迅速投入工作。1998年，她创办了中国第一个高端人物访谈节目《杨澜访谈录》。那时，很多人劝她做轻松的生活类节目，但她偏要把镜头对准最硬核的政要和思想家。她采访过上百位各国政要，也对话过国内外知名的企业家、科学家和艺术家。' },
      { type: 'p', text: '“我不相信女性只能局限在琐碎生活中，”她说，“我想用访谈触摸更大的世界。”有一次采访基辛格，她直接追问：“如果有机会重新选择，您会不会改变某些外交决策？”对方愣了一下，随后笑着回答：“年轻女士，你的问题很有挑战性。”通过《杨澜访谈录》的坚持，她让自己成长为可以与世界重量级人物平等对话的女性。' },
      { type: 'p', text: '2005年，她又开创了《天下女人》栏目，舞台转向女性群体，给予普通女性发声的机会。节目开篇语“女人为什么爱说话”，看似轻松却蕴含深意。“人类智能的飞跃来自语言的发展，女性在其中贡献巨大。语言不仅是交流，更是情感的链接和文明的记忆。”' },
      { type: 'p', text: '在这个节目里，她邀请农妇、白领、创业者、病患走上荧屏，让她们讲述真实的故事。她希望：“不管是否籍籍无名，每一个女性都能说出自己的故事，对社会表达自己的观点。”节目播出后，不少观众来信说：“我第一次在电视里看到和我一样的女人。”杨澜说：“媒体的责任，不只是传播，更是唤起。”' },
      { type: 'p', text: '随着话题与受众的扩大，杨澜意识到，仅靠电视节目不够。2007年，她开始尝试办论坛。2014年，“天下女人国际论坛”正式落地；2016年，“天下女人研究院”成立；随之诞生的，还有她命名的“Her Village（她的村庄）”。' },
      { type: 'p', text: '这个名字的灵感，来自一次印度之行。杨澜在甘地纪念馆看到一句话：“世界无论多大，都是一个村庄；村庄无论多小，都是一个世界。”她说：“女性之间的理解、体谅和支持，就是一个巨大的力量。我们不是孤军奋战，而是连接在一起的。”' },
      { type: 'p', text: '自2014年起，天下女人国际论坛上，有二百多位中外嘉宾分享关于心理健康、领导力、社会责任的话题。杨澜常常被现场的热烈氛围打动：“当女性聚在一起，她们是如此勇敢、如此自由，甚至会面红耳赤地争论。这是她们在男性为主的环境里很少展现的。”' },
      { type: 'h', text: '谁该回答“如何平衡家庭与事业”' },
      { type: 'p', text: '在传统的社会语境里，几乎所有成功女性在接受采访时都会被问到一个“标准问题”——你如何平衡家庭和事业？' },
      { type: 'p', text: '杨澜很清楚这个问题背后的潜台词：女性似乎必须先证明自己是好妻子、好母亲，然后才有资格去谈事业的成功。如果作为妻子离婚了，就被视为失败；如果孩子没考上好学校，就好像母亲失职。“我们都在默默把这些标准强加在自己身上。”她决定用反问打破这个惯例。在自己的访谈节目中，她开始把这个问题抛给男性嘉宾——那些在商界、政界叱咤风云的成功男士们。“我问他们：请问你是怎么平衡家庭和事业的？”杨澜笑着回忆，“有的人当场非常紧张，以为我要探究他们的私生活；也有人满脸困惑，觉得这完全不是一个男人该被问的问题。对他们来说，男人就该在外打拼，为什么要回答这种问题？”' },
      { type: 'p', text: '这一问，打破了固有叙事，让许多人第一次意识到，为什么“平衡”的责任只落在女性身上？这背后，折射的是曾经根深蒂固的性别分工：事业属于男人，家庭属于女人。而如今，杨澜发现情况正在发生变化。人们开始意识到，家庭与事业的平衡并不是女性的“独家义务”。越来越多的女性拒绝被这一问题框住，越来越多的男性也开始意识到，他们同样需要承担家庭责任。' },
      { type: 'p', text: '“今天，几乎没有人再理所当然地认为，只有女性才需要回答这个问题了。”杨澜说，“不平衡很正常，为什么必须解释？今天的女性越来越有自我驱动力，而不是被外界的完美人设绑架。这是这个时代最值得骄傲的地方。”' },
      { type: 'p', text: '作为主持人和记者的杨澜，总是敢于拿起自己的“武器”——用提问去打破社会旧有叙事的窠臼。她说之所以有这样的“胆量”，与自己童年的家庭教育分不开。她是家里的独生女，但父母从未因为她是女孩，就把她框进所谓的“乖巧”模式里。' },
      { type: 'p', text: '“我小时候特别喜欢玩泥巴、爬树，是个挺野的孩子。”她回忆，“可我的父母从来没有说，女孩子就要玩过家家，要学会补衣服、抱洋娃娃。他们只会说：小心点，别摔伤了。”正是这种宽松和信任，在她幼小的心里就种下了一颗“我可以”的种子。' },
      { type: 'p', text: '等到读书的时候，父母同样没有设限，而是不断鼓励她要有真才实学。杨澜的母亲是一位工程师，年轻时差点因家境贫困而被迫放弃读书，是班主任亲自登门劝说，才让她得以继续学业，最终成为家族里的第一位女大学生。也正因此，母亲常告诫她：“女孩子必须要有自己的学问，将来才不用看别人的脸色。”' },
      { type: 'p', text: '这种信念深深烙进杨澜心里。她很小就明白，男人能干的事情，女人同样可以干，尤其在学习和事业上，没有理由不比别人做得更好。“父母没有给我贴上‘乖乖女’的标签，而是让我做回自己。这种教育，让我在后来的人生路上，有勇气去质疑、去突破，也让我的‘大女生’气质有了最初的土壤。”' },
      { type: 'h', text: '大胆做自己，大步走四方' },
      { type: 'p', text: '杨澜发现，直至今天，一些女性仍习惯将幸福寄托在“遇到白马王子”“买到名牌包”“住豪宅、开豪车”“孩子上名校”上，但她认为，幸福应该像花一样，由自己的内在生发而来。' },
      { type: 'p', text: '2009年，杨澜在《天下女人》节目中第一次完整提出“幸福力”概念。她并不想把它当作一句口号，而是希望真正建立在学术和科学的支撑之上。“我不是随便说一句‘大家要幸福’，而是希望能告诉女性，幸福是一种能力，可以被学习、被培养。”为了这个目标，杨澜几乎做了一个校园之外的“研究生”。她不仅阅读了200多本专业书籍，还在节目和论坛中采访心理学家、教育学者，甚至神经科学领域的专家，试图把这些知识消化后，用更通俗的方式讲给普通观众听。' },
      { type: 'p', text: '“比如积极心理学，我读了塞利格曼等人的研究，理解到幸福不是偶然的好运，而是可以通过实践获得的一种心理状态。又比如我看弗洛姆的书，他强调爱与自由的关系，这些都让我重新思考女性在亲密关系中的自我。”' },
      { type: 'p', text: '杨澜把这些学习最终凝练成“幸福力六边形”：积极情绪、投入状态、人际关系、意义感、成就感和悦纳自我。而“悦纳自我”是她在原有心理学“五大支柱”理论基础上提出的新维度。“如果我们不能和自己和解，接纳自己的不完美，就无法真正建立积极的人际关系，更无法与世界走向和谐。”' },
      { type: 'p', text: '成功出版专著《幸福力》之后，杨澜又驱动自己“向前一步”，为了不让“女性议题”只停留在一句句干瘪的呼吁口号上，她决定筹备《大女生》一书的撰写。“还是老规矩，先做功课。”她请女性学研究方向的教授为她开了一份书单——超过200本经典著作。她一一读完，做笔记、写卡片，还把其中的理念带到采访和写作中。她希望这些理念不只是高高在上的理论，而是可以通过她的大量阅读、采访和思考，一点点转化为普通人能理解的语言。' },
      { type: 'p', text: '在书中，杨澜鼓励女孩“大胆做自己，大步走四方”。她说：“女性的成长不应被完美人设绑架，而要用成长的思维取代。”而最令她感到欣慰的是，到了女儿这一代，平等意识仿佛与生俱来。她记得，女儿在青春期时，她提醒过一句“不要穿太暴露”，女儿立刻反驳：“妈妈，全世界的妈妈都应该教育儿子尊重女性的穿衣权利，而不是教育女儿遮掩。”她还记得，女儿在五六岁时就曾问她：“为什么白雪公主只能躺在那里等待陌生人的吻？而且那个人没有征得她的同意。”' },
      { type: 'p', text: '这些问题让杨澜震撼，也让她看见希望，当一个女孩子在爱与尊重的环境中成长，当平等理念融入日常认知，她必然会这样去思考。' },
      { type: 'p', text: '三十年后，杨澜再次回望世妇会，感慨万千。当年大会上那些关于性别平等、女性发展的深刻议题，如今已化作无数女性生命里的真实改变。那些曾让她震撼的、关于女性自我觉醒与价值追寻的问题，也让她清晰看见希望的模样——女儿这一代，天然地觉得不应把人生交给命运，而是要主动去选择。' },
      { type: 'p', text: '“要勇敢突破头脑里的藩篱。”这是杨澜在采访中反复强调的一句话。她提醒当下的女性，不要让旧有的性别角色框住想象的边界；要学会与自己和解，拒绝完美主义，不必苛求无瑕才值得被尊重；更要在任何年龄都保持学习与成长的心态——“30岁该干什么，50岁该干什么”，从来只是世俗的刻板印象。只要心态开放，人生随时都能重新绽放。她引用自己最喜爱的一位女性作家弗吉尼亚·伍尔夫的话：“女人不是供人欣赏的花瓶，而是在草原上随风起舞的旋律。”这是她的总结，也是她的寄语。' },
    ],
  },
  {
    id: 'jiang-mengnan',
    kind: 'profile',
    date: 'Apr 4, 2022',
    read: 10,
    lang: 'zh',
    illus: 'assets/illustrations/portrait-gesture.svg',
    heroIllus: 'assets/illustrations/portrait-gesture.svg',
    title: '江梦南：无声世界的"响亮"青春',
    titleEn: 'Jiang Mengnan · A resonant youth in a silent world',
    dek: '半岁因药物失聪，她考入清华博士。这是一个在寂静里长出声音的故事。',
    tags: ["profile","清华","听障","励志"],
    body: [
      { type: 'p', text: '2022年3月，感动中国2021年度人物揭晓，和杨振宁等杰出人物一同登上颁奖台的90后女孩江梦南，迅速刷屏网络。从一名听障女孩成长为清华大学医学院博士生，她的励志人生，荡气回肠，感动众人。' },
      { type: 'h', text: '江梦南：无声世界的“响亮”青春' },
      { type: 'p', text: '江梦南，清华大学医学院在读博士研究生，获评感动中国2021年度人物' },
      { type: 'p', text: '采访江梦南还是有些不同，记者的声音通过软件同步成文字，电话那端立马传来她的声音。清脆、明快，沟通酣畅淋漓，完全想象不出，江梦南是一名听障人士。她说她一边接受采访，一边还在忙着手里的课题，时间永远不够用，一如她一直追梦的奔跑。' },
      { type: 'h', text: '“救死扶伤”是梦想' },
      { type: 'p', text: '再有一段时间，清华大学医学院博士生江梦南就要毕业了，每天“脚后跟打着后脑勺”地赶进度、写论文。' },
      { type: 'p', text: '“我现在在做的是通过深度学习方法对T淋巴细胞受体和抗原之间的互相识别进行建模预测，该研究将有助于进一步探索复杂的免疫系统，对疫苗研发、肿瘤免疫治疗具有一定的意义。”救死扶伤，探索生命健康领域的难题，似乎是江梦南从小的梦想和志向。' },
      { type: 'p', text: '当年，当医生的姥姥发现外孙女喜欢模仿医生看病，动作有模有样，便说，“你将来一定会成为真正的好医生！”江梦南一直记着姥姥的话，直到上大学选专业时，意识到医生出诊要戴口罩，那时还仅能靠唇语沟通的她，只好选择了药学专业，又因为听不见声音，不方便操作一些化学实验，研究生时选择主攻计算机辅助药物设计专业。' },
      { type: 'p', text: '2018年5月，江梦南被清华大学医学院生物信息专业录取为博士研究生，专业跨度有点大，计算机编程、数学统计等知识大都是从读博才开始系统学习的。记得刚开始课题组开会的时候，大家七嘴八舌头脑风暴，她坐在一旁插不上话，“说”的跟不上，连她最擅长的看唇语“听”的本领也失灵了。新专业新词汇，江梦南的大脑系统没有足以支撑她快速读懂大家唇语的“内存”，她感到有些懵，甚至感觉比小时候学说话还难。' },
      { type: 'p', text: '半岁时因药物导致失聪的她，儿时靠看着父母的口形、舌头的位置，摸着父母的喉咙、感知声带的震动去学语，每一个发音她都要练习上万遍，最终形成肌肉记忆才算过关。' },
      { type: 'p', text: '她的人生本就是一路“升级打怪”，这点困难岂能难倒她。“没什么秘诀，就是比别人花更多精力和时间。”她向老师和同学要来必学内容的清单，一点点地啃下来，很快她不仅解锁了写代码做编程等新技能，在小组讨论时也能“赶上趟”了，敲击代码、搭建模型,她的自信回来了。' },
      { type: 'h', text: '坚持才有希望' },
      { type: 'p', text: '“坚持”两个字是父母赐予江梦南的生命密码。她一直相信：“不是因为有了希望才去坚持,而是因为坚持才有希望。”' },
      { type: 'p', text: '“感动中国”颁奖现场，江梦南一字不差地读出了主持人敬一丹的唇语：“我非常佩服你的爸爸妈妈”。她感慨万千地说：“我学会说话是一个奇迹，父母的坚持、不放弃，教我学会了读唇语，这是个非常宝贵的能力。”' },
      { type: 'p', text: '江梦南出生在湖南莽山瑶族乡永安村，父母都是莽山民族学校的老师，他们给她起了一个非常诗意的名字，寄语“梦里江南,岁月静好”。然而,命运却背道而驰。不到6个月时她突然持续高烧20多天，服用各种退烧药导致她听力丧失。医生下了判决书：由于是“语前失聪”，学会说话几乎不可能。父母如坠深渊，但他们不甘心，不能就这样把女儿留在无声的世界。' },
      { type: 'p', text: '喝了无数苦药汤、扎了无数祖传针……在大半个中国的各大医院间奔波成了江梦南的童年“游记”，也成了父母的失望之旅，却从没想过放弃。明知没有希望却还是坚持给女儿买了助听器，渴望女儿听到哪怕一点点声音。' },
      { type: 'p', text: '日子在“无望”的训练中慢慢过去了三个月，一天，小梦南在玩球，忽然球滚走了——“啊啊。”安静的房间里，父母瞬间怔住，这一声含糊不清的声音让他们如同抓到从深渊向上腾挪的绳索，教会孩子正常说话的信念更加坚定。' },
      { type: 'p', text: '为了给女儿更专业的训练，妈妈专门到长沙学习言语康复，拿到了当地第一个言语康复师证。她天天怀抱女儿坐在镜子前练习，从简单的音节开始，说清楚一个字通常是练上万遍。一年又一年，奇迹终于发生了，镜子在失去光泽，江梦南的言语能力却赶上了同龄人！' },
      { type: 'p', text: '当江梦南坐在高考的考场上，看到作文题目《早》时，不禁想起了小时候天不亮父母就大包小包地带她赶路看病的日日夜夜，她含着热泪写下了父母的艰辛。' },
      { type: 'h', text: '想和你们一样“普通”' },
      { type: 'p', text: '“你觉得，你和我们一样，我们觉得，是的，但你又那么不同寻常。先飞的鸟，一定想飞得更远。迟开的你，也鲜花般怒放。”这是江梦南获得感动中国2021年度人物的颁奖词，很多观众为她的事迹潸然泪下。' },
      { type: 'p', text: '成长、求学、生活，每一步都是从“困难模式”中走来，江梦南太不普通了，然而她的所有努力，只是为了和普通的孩子站在同一起跑线上。' },
      { type: 'p', text: '她记得上幼儿园时第一次意识到自己和别人不同，便向父母抱怨，“为什么我听不见，为什么是我？”父母耐心地告诉她，与其怨天尤人，不如更加努力去克服。从此，江梦南追求“要跟大家一样”，“哪怕听不见，也要和其他同学站在同一起跑线上。”' },
      { type: 'p', text: '上小学时，她作为旁听生被普通学校接收。没想到这个不被看好的旁听生，入学第一年就考了全年级第一。学校有给优等生颁奖的惯例，江梦南抑制不住喜悦，早早就选好了一身漂亮衣服，激动地等待走上领奖台。然而，直到结束也没听到自己的名字，原来在江梦南之前，学校没有接收旁听生的先例，一时疏忽没有给她也准备一份奖状。憋着一路的委屈和失望回家，她放声大哭，并立下誓言，要继续考“第一”，一定要登上领奖台。' },
      { type: 'p', text: '之后的江梦南果然每年都凭借优异的成绩登上了领奖台，四年级的时候学校将她转为正式学生。在父母的帮助下她自学了五年级的课程成功跳级，令无数人刮目相看。' },
      { type: 'p', text: '不想被当做弱者，江梦南小学毕业后到离家300公里的郴州读重点中学，学着一切靠自己。有一天，不放心的妈妈躲在校园角落，远远观察她的一举一动。江梦南似乎感知到了什么，猛一转头，发现了绿化带后的妈妈，跑过去扑进妈妈的怀里。然而她清楚地知道，只有离开父母离开家才能真正长大……2011年，她如愿考上吉林大学，离家3000公里，更远了，这一次，她更是执意独行，越来越自信的她，已然让身边人忘记了她是位听障人士。' },
      { type: 'p', text: '2018年，江梦南在吉林大学即将硕士毕业时植入了人工耳蜗，失去26年的听力回来了。一切都那么喧嚣而新鲜，树上布谷鸟叫声让她觉得新奇。而对父母来说，终于能和女儿通上电话了。' },
      { type: 'p', text: '“对于需要帮助的人，不用刻意去问他们需要什么，就把他们当成普通人，这会让他们没那么大的心理压力。”如今的江梦南是清华大学学生无障碍发展研究协会第五任会长，组织协会活动、无障碍论坛、举办无障碍理念体验活动……江梦南身体力行地向公众普及无障碍理念，在她看来，在看不见的地方“铲平”障碍，这才是比较体面的帮助方式。' },
      { type: 'p', text: '“你已经走这么远了，为什么不试试人生还有多大的可能性？”2018年夏天，植入耳蜗前，医生的话她铭记在心。' },
      { type: 'p', text: '毕业后去哪里工作、做什么工作……江梦南现在还不确定，但可以确定的是无论做什么，都要为残障人士服务：我愿做些事情，让和我有类似经历的人不再那么辛苦和艰难，让他们的人生充满希望。' },
      { type: 'p', text: '“今后无论在哪里，我都要把父母接在身边，未来还要带父母去西藏、去青海湖，去看看远方美丽的风景……”' },
      { type: 'p', text: '所有非凡都有着非同寻常的付出，所有梦想都因为超越梦想的执着才得以成真。江梦南，敢于追梦，以超常奋斗成就传奇。相信，她的未来会更精彩。' },
    ],
  },
  {
    id: 'tian-qinxin',
    kind: 'interview',
    date: 'Dec 7, 2024',
    read: 12,
    lang: 'zh',
    illus: 'assets/illustrations/hands-letter.svg',
    heroIllus: 'assets/illustrations/hands-letter.svg',
    title: '田沁鑫：受到召唤，做一个光影世界的筑梦者',
    titleEn: 'Tian Qinxin · Summoned — a dreamer in the world of stage',
    dek: '从敦煌到国话，她在光影与舞台间穿行，自称"受到召唤的人"。',
    tags: ["interview","话剧","敦煌","导演"],
    body: [
      { type: 'p', text: '在中国话剧的璀璨星河中，有这样一位女性导演，她以笔为剑，以心为灯，照亮了无数观众的心灵深处。她，就是田沁鑫，一个用光影构筑梦想世界的筑梦者。12月7日，她带着精心创作的音乐话剧《受到召唤·敦煌》，在国家速滑馆“冰丝带”开启了一场与观众心灵深度交感的古今互动。' },
      { type: 'h', text: '田沁鑫：受到召唤，做一个光影世界的筑梦者' },
      { type: 'h', text: '本刊记者/王梓蓉' },
      { type: 'p', text: '在距离《受到召唤·敦煌》首演还有10天的时候，记者在位于北京通州的排练场采访了中国国家话剧院院长、音乐话剧《受到召唤·敦煌》导演田沁鑫。' },
      { type: 'p', text: '半年前，田沁鑫带领主创团队到敦煌采风，行走在历史的沃土上，感觉自己像是跨越了千年时光。千年壁画上自在舒展的伎乐飞天，头顶层层叠叠的藻井，它们明明都是静止的，但看着看着仿佛一切都飞升起来。“敦煌是充满律动的”，她决定这部剧不能少了音乐——音乐话剧由此而来。' },
      { type: 'p', text: '从中秋节全体主创重装集结，正式进入话剧排练阶段，到如今进入首演前的最后冲刺阶段，田沁鑫和主创们一直沉浸在饱满的创作激情中。梦里梦外都是敦煌壁画中庄重慈祥、略带笑意的面庞，反弹琵琶的飞天意象、洞窟中的瑰丽色彩、月牙鸣沙之间的气息和温度……她的人生仿佛注定和敦煌有一次交汇，在冥冥之中受到召唤。' },
      { type: 'p', text: '采访当天，田沁鑫用小巧的发卡把夹杂着白发的齐肩短发别得一丝不乱，一身新中式的薄棉袄衬托得她极其柔和，但当眼睛对准镜头时，人又变得犀利起来。她对记者说，“昨晚又排练到3点”，然后呷了一口红茶说：“咱们开始吧……”' },
      { type: 'h', text: '让敦煌年轻起来' },
      { type: 'p', text: '《中国妇女》：《受到召唤·敦煌》集结了大量年轻演员，为何如此“重用”年轻人？' },
      { type: 'p', text: '田沁鑫：在我作为导演的职业生涯中，有幸接触并培养了许多年轻演员，从早期的袁泉、辛柏青等人开始，他们与他们的老师一同在剧院中与我合作，共同在舞台上锻炼和成长，建立了亲密的工作关系。当我担任院长后，开始接触更多的青年工作人员。我惊讶地发现，剧院里居然聚集了如此多的年轻人。他们充满了活力和创造力，为剧院带来了新的气息和动力。' },
      { type: 'p', text: '党的二十届三中全会通过的《中共中央关于进一步全面深化改革、推进中国式现代化的决定》中强调，“培育形成规模宏大的优秀文化人才队伍”。对于国家话剧院来讲，在培养青年演员、推动文化强国的发展上面，我们必须出一份力。' },
      { type: 'p', text: '国家话剧院在表演艺术方面是一个非常优质的平台，有一代又一代的演员在国家话剧院的舞台上成长起来。我的前任院长、前前任院长经常说的一句话是：“服务艺术家”，这是国家话剧院的传承。所以在《受到召唤·敦煌》排练过程中，我邀请到音乐剧演员出身的孙红雷，专门来给青年演员传授舞台表演上的一些经验。还有宋佳、陈数等演员，他们都很愿意参加剧院平时的活动和表演交流，对于青年演员来讲是很好的学习机会。' },
      { type: 'p', text: '同时，年轻人也在反哺着剧院的发展，让剧院能够在尝试创新和探索方面有很多年轻人来支持。我平时很少用“刻苦”形容年轻人，但是这次以主演张艺兴为首的年轻演员们真的很刻苦、很努力，他们让我感到非常欣慰和自豪，值得我去学习，也让我更加坚信，剧院未来一定会在他们的手中绽放出更加璀璨的光芒。' },
      { type: 'p', text: '《中国妇女》：为排练这个剧目，您是第一次去敦煌吗？有一种什么样的感觉？' },
      { type: 'h', text: '田沁鑫：是的，我一直说要去敦煌，但是一直没有时间，直到做这部戏，我才得以踏上敦煌的土地。我母亲是画工笔画的，所以像佛手、菩萨这些描绘我小时候就看到过。得知我要去敦煌，母亲特地嘱咐我要去看哪些地方。母亲说她当年在敦煌看一个藻井，能一直看一上午。看着看着，她感觉那个藻井动起来了，像万花筒一样，她恍然明白飞天为什么会飞。抵达敦煌后，我给母亲打了一个视频电话，激动地说“我在九层楼下面了！”当我自己站在藻井之下，也突然明白了母亲所说的意境，是一种立体的感受，一种玄妙的、高维的感受。' },
      { type: 'h', text: '我惊叹于早在1500年前，中国的线描虽是旋肘式的毛笔线描，但却有像钢笔一样的直线和各种线条的走向，古人怎么会有这样的功力来做到这一点？还有色彩的繁复，不单是造像的璎珞、佛像的柔美，还有很多繁复的色彩绚烂得难以用语言形容。' },
      { type: 'p', text: '《中国妇女》：是什么让您萌生了想让敦煌“年轻”起来的念头？您希望通过这部戏传递给年轻人什么？' },
      { type: 'p', text: '田沁鑫：今年是敦煌研究院成立80周年，习近平在敦煌莫高窟考察调研时强调，敦煌文化属于中国，但敦煌学是属于世界的。把莫高窟保护好，把敦煌文化传承好，是中华民族为世界文明进步应负的责任。' },
      { type: 'p', text: '对真正的敦煌艺术，我们是望尘莫及的，只能怀着无限敬仰。但我们不能只停留在尊重的层面上，否则我们就会畏手畏脚、止步不前。所以我想通过现在观众非常喜爱的青年演员，比如张艺兴，和我们活力四射的青年团队，以及年轻化的主创艺术家团队，合力让敦煌更加活态化一些，让敦煌艺术年轻起来，让更多的年轻人能感受到敦煌。从而激发年轻人对敦煌艺术的兴趣和热爱，让他们意识到传统文化并不是遥不可及的古董，而是可以融入当代生活、激发创造力的灵感源泉。' },
      { type: 'h', text: '女性可以再大胆一些' },
      { type: 'p', text: '《中国妇女》：近年来，不论是女性自身的观念和意识，还是社会对女性的期待和评价都发生了很大变化，您所塑造的女性形象是否也随时代变化而有所不同？' },
      { type: 'p', text: '田沁鑫：我早期作品中的女性形象，更多地反映了封建时代社会对女性的一些期待和评价。例如，萧红笔下《生死场》中的王婆，她具有反抗精神，但当她的丈夫向地主讨债失败后，她的精神支柱坍塌，最终选择了自杀。这样的评价其实是封建审美下的一种局限，也体现了当时像萧红这样的女性作家所受的社会束缚。随着新中国的成立，毛泽东提出“女性能顶半边天”的观念，社会开始转型，逐渐开放，为女性提供了更好的社会环境。但即便如此，有些女性仍然受到封建审美的束缚，她们自己束缚了自己，没有意识到这种封建审美是可以打破的。' },
      { type: 'p', text: '实际上，独立的精神并不取决于性别，而是取决于一个人的思维能力和精神世界。因此，我也努力在角色的塑造上打破封建审美的束缚，鼓励女性能够更加有创造力，不给自己设限，活出自己的风采。' },
      { type: 'p', text: '《中国妇女》：今天的影视戏剧行业，女性创作者越来越多，您如何看待这种现象？能否结合您个人经验，给年轻的女性创作者一些建议？' },
      { type: 'p', text: '田沁鑫：“乾道成男，坤道成女，乾知大始，坤作成物。”中国古代智慧里蕴含着深刻的阴阳哲学。这种哲学思想认为，男女两性如同天地、日月、山川与河流，彼此依存、相互补充，共同构成了宇宙的和谐与完整。所以，我觉得性别不应该成为某种对立，而是相互帮衬。但在现有的影视或艺术作品中，尤其是以女性为主要角色的作品中，这种“平视”的视角还远远不够。像比较火的宫廷戏，还有现实题材作品中真正的“大女主”并不多，即便有，形象树立得也颇为挣扎。' },
      { type: 'p', text: '我希望大家在女性角色的设定和创造上再大胆一些。像宋佳饰演的张桂梅老师，十分受观众喜爱，但像这样的好剧、爽剧仍然太少。建议女性创作者更加勇于挖掘和表达自己及周围女性的真实经验和情感，尝试用新的方式去讲述故事，展现女性的多样性、复杂性以及多彩斑斓的精神世界。' },
      { type: 'h', text: '讲好中国故事' },
      { type: 'p', text: '《中国妇女》：您常说“用情用力讲好中国故事”，讲好一个故事的关键是什么？' },
      { type: 'p', text: '田沁鑫：在中国国家话剧院成立20周年之际，习近平总书记给国家话剧院的艺术家回信，信中强调：“希望你们再接再厉，紧扣时代脉搏、坚守人民立场、坚持守正创新，用情用力讲好中国故事，创作出更多无愧于时代、无愧于人民的优秀作品，为新时代文艺事业繁荣发展、为丰富人民精神世界作出更大贡献。”' },
      { type: 'p', text: '要讲好中国故事，首先必须注重社会主义核心价值观，确保个人树立正确的世界观、人生观、价值观，使自己的思维方式和精神世界更好适应艺术表达的需要。只有树立了正确的观念，我们的作品才能具有思想性，进而影响人、作用于心灵。如果作品既不能作用于思想，也不能触动心灵，仅仅停留在视觉或其他层面，我认为这样的作品谈不上“讲好中国故事”。' },
      { type: 'p', text: '为了讲好中国故事，我们可以从中华优秀传统文化中汲取素材和灵感，中华历史上的经典作品都是我们创作的重要源泉和精神滋养。同时，我们的作品需要具有感动和感召的力量，以及平等交流的能力。' },
      { type: 'p', text: '《中国妇女》：通过您的作品，能感受到您是一个喜欢并善于创新的人，您如何在过去与未来、传承和创新之间找到平衡？' },
      { type: 'p', text: '田沁鑫：当前，在戏剧方面践行习近平总书记提出的“两创”要求，特别是创造性转化、创新性发展方面，重塑中国的表演艺术精神是这个时代中国艺术家们需要考虑的重要课题。' },
      { type: 'p', text: '话剧是“站着说话”的剧种，传到中国100多年了，我们的语言方式做到了努力践行创造性转化、创新性发展。在我看来，话剧的发展还要和时代同步伐，比如科技和艺术的结合势在必行。' },
      { type: 'p', text: '《受到召唤·敦煌》有四个多媒体团队，还要特别感谢敦煌研究院对我们的支持，给我们提供了大量的高清图片。我们想利用科技手段，试图给观众呈现一部分修复好的漂亮的造像壁画；尝试应用AI制作，去模拟在沙漠上行走等等这种难以实现的真实感受；跟中影集团合作拍摄电影，与“CNT 现场”网络直播类平台合作，播放第二现场等。这些尝试都是在适应互联网时代，包括数字化的国家战略。我们走得很严谨，但不拒绝合作。在合作过程中，大家会发现有很多有趣的碰撞，在这个过程中感受守正与创新的平衡。' },
      { type: 'p', text: '如果不守正，话剧艺术的基础就没有了；如果不创新，话剧艺术也就失去了生命力。所以我们必须这样去做，这也是中国国家话剧院要去做的事情。我们秉承的创作态度是努力刻苦，像小工匠一样不断钻研，严肃尊重历史和文化，但是形式可以活泼。也希望通过一个个剧目的创作，让更多人看到源远流长的东方文明之美，感受到中华文化的无穷力量与深刻召唤。' },
    ],
  },
  {
    id: 'su-qin',
    kind: 'profile',
    date: 'Mar 3, 2024',
    read: 18,
    lang: 'zh',
    illus: 'assets/illustrations/portrait-contour-1.svg',
    heroIllus: 'assets/illustrations/portrait-contour-1.svg',
    title: '苏琴：向险出发，逆行救援"铁娘子"',
    titleEn: 'Su Qin · The Iron Lady of Blue Sky Rescue',
    dek: '她参加过三百余次救援，热血点燃向险而行的勇气，被誉为民间救援力量中的"铁娘子"。',
    tags: ["profile","蓝天救援","应急","公益"],
    body: [
      { type: 'p', text: '2024年3月3日，纪念“三八”国际妇女节暨表彰大会上，苏琴身别“全国三八红旗手标兵”缎带，她利落的短发，麦色的皮肤，一身制式的蓝天救援队服，在一众人群中显得格外精神、干练。' },
      { type: 'p', text: '作为不多见的女救援队长，这位80后“铁娘子”的经历也非同寻常：跳进湍急的洪水中抢险，悬在万丈山崖上救人，当总协调率队远赴土耳其地震灾区……十几年来，她和队友们参加了700多起各类救援及城市寻人行动，于惊心动魄中挽救了一条条生命，一个个家庭。' },
      { type: 'p', text: '一次次逆风而行，一次次迎险而上，为人女、人妻和人母的她难道不害怕吗？' },
      { type: 'h', text: '救灾，大爱无疆' },
      { type: 'p', text: '2023年2月6日，当地时间凌晨4点17分，土耳其卡赫拉曼马拉什省，熟睡的人们完全没意识到，厄运会向他们突然袭来。几乎一瞬间，一场7.8级的大地震在毫无预兆的情况下撕裂了整个城市，空天炸裂，大地翻腾，建筑崩塌，道路中断……仿佛整个世界都在崩溃的边缘。' },
      { type: 'p', text: '仅仅几个小时后，在离第一次地震约60英里的地方，又发生了另一起7.8级的大地震。这一次的震动更加剧烈，破坏力也更加强大。房屋倒塌的声音、人们哭喊的声音、汽车碰撞的声音……所有的声音交织在一起，构成了一幅惊心动魄的灾难画面。' },
      { type: 'p', text: '北京时间2月6日9点17分，地处合肥市老城中心的淮河路步行街上，农历兔年元宵节的红灯笼仿佛还未完成装点的使命，一个个红彤彤、喜洋洋地等着工人们来取下。在这里，昨夜团圆饭的锅气还未散去，人们意犹未尽地走出春节，走进新的一年……' },
      { type: 'p', text: '苏琴的手机屏幕一亮，微信通知栏里弹出“土耳其发生大地震”几个字，她下意识地看了一眼杵在房间角落里的行囊，心想难道新年“第一差”就这样突如其来？果然，中国政府第一时间启动紧急人道主义援助机制，苏琴没有片刻犹豫，吹响了合肥蓝天救援队的集结号，8个精兵强将迅速召集完毕。一天后，来自全国各地127位穿着蓝色队服的志愿者们在武汉机场集合，他们携带着3900公斤的救援装备和物资向土耳其挺进。' },
      { type: 'p', text: '“这就是咱们中国的蓝天救援队！”机场的路人们端起手机，纷纷拍下这出征的一幕。身高未到170厘米的苏琴混在人群中脚下生风，一瞥而过时很难辨出她是一名女队员，更不会想到她是这支百人救援联盟的的总协调。' },
      { type: 'p', text: '2月9日凌晨一点多，救援队乘坐的飞机抵达土耳其伊斯坦布尔机场。随着电梯徐徐下行，一队黄皮肤、蓝制服的中国志愿者整整齐齐地列队出现，苏琴突然听到掌声，然后看见土耳其百姓的身影一截一截地在眼前升起。' },
      { type: 'p', text: '在语言不通的情况下，看着不由自主起立的土耳其人民，争前恐后让出座位给救援队休息的土耳其人民，端着食物递到自己嘴边的土耳其人民，苏琴的心跳抑制不住地快起来，眼角有一点点湿润。在灾难面前，哪里还有什么国别之分，爱才是人类共同的语言。' },
      { type: 'p', text: '经过飞机转乘，苏琴和队员们历经十多个小时抵达位于震中附近的土耳其马拉蒂亚。顾不上休息，救援队立刻按各自技能兵分多个战斗组昼夜展开搜救。地震发生的两天内，灾区又经历大雪和严寒天气。最低气温仅-10℃，最高气温也不过-2℃，这给救援工作带来极大困难。' },
      { type: 'p', text: '虽然接受过很多次训练，但从未亲眼见过大地震的苏琴，还是被眼前的满目疮痍给震惊了。人类文明的迹象已无踪影，废墟中，屋顶塌陷，窗户破碎。屋内家具的碎片、衣物、书籍等像被巨大的力量吞噬过，稀碎地散落一地。一些建筑物甚至完全坍塌，楼层与楼层之间已几乎没有间距，远看像馅饼一样挤压在一起，让人无法想象这里曾经的生活场景。' },
      { type: 'p', text: '队员们手持探测仪器，在废墟中找寻生命的迹象。虽然已过黄金72小时的抢救时间，但大家依然不想放弃任何一个生还的机会。搜救过程中仍有余震，原本仔细勘探好的位置打下去，很可能会因余震带来的新的偏差而前功尽弃。“近在咫尺，却远在天边”，在缝隙中找人，最令人折磨的莫过于看得见却够不着的场景。' },
      { type: 'p', text: '随着一批批救援队员陆续抵达，苏琴需要调度的工作量也越来越大，她一边当着近200人队伍的总协调，一边钻入缝隙狭小的探洞里救援。因为搜救工作面越往下越小，男队员个子较大，钻不进去，遗憾的是，苏琴并未亲自营救到鲜活的生命，但来自中国的救援力量一共救出30多个幸存者，仅苏琴所在的小团队就营救出3人。' },
      { type: 'p', text: '但更多的时候，他们面对的是失去生命的尸体。等待了100多个小时却在最后一刻断气的90岁老人，一个原本幸福快乐的小女孩，又或是齐齐整整的一家四口……' },
      { type: 'p', text: '等苏琴再回到合肥，街上的“年味儿”已彻底更替成新年后的忙碌。“非常疲惫；8天廋了8斤”，一年多过去，当她回忆起这段往事时，仿佛只记得这些，其余的细节也许是因为太过惨烈而被默默忘记。' },
      { type: 'h', text: '抢险，大水无情人有情' },
      { type: 'p', text: '2020年合肥的夏天，令苏琴刻骨铭心。头顶的天仿佛漏了，降雨量达到了往年的3倍。暴雨袭击江淮大地，从新安江、长江到巢湖、淮河，湍急的洪水到处肆虐。' },
      { type: 'p', text: '7月14日，皖南一山区需要潜水员下水排查搜索，当天18时，苏琴带着10名队员赶到救援现场，五个多小时抵达后，四周已漆黑一片。苏琴一抬手腕，跟随她多年的橙色户外手表亮了起来，她触摸表盘，看到天气预报显示第二天大雨，山区洪水一旦下来，水中基本没有任何能见度了，大家顾不上休息，只能决定连夜下潜。' },
      { type: 'p', text: '泥泞中，到处都是挖土机隔开的河道，不仅坡陡而且石子很滑，再加上夜晚能见度低，搜潜难度系数很大，十分危险。苏琴摔倒在地，磕破了腿。但作为全队唯一的女潜水员，苏琴顾不上伤痛，一头扎进冰冷的山泉中，搜索到深夜……任务结束时，她的手臂已冻得发黑，宾馆的洗手间中，潜水服都没有力气去脱下来，在热水下冲了半小时才缓了过来。“我是队长，必须打头执行下潜任务。”尽管危险重重，但苏琴的心中只有完成任务的踏实感。' },
      { type: 'p', text: '即便是做救援工作，天天生活在城市里，也会忘记“水的无情”。在灾区，洪水最深处可达8米高，二层楼里的东西都在房间里飘来飘去。“往年我们也多次参与灾害救援，大家看过了太多人间悲剧，但身处现场那种视觉冲击，还是让我的心揪得厉害。”' },
      { type: 'p', text: '有一次紧急救援，苏琴回忆起当时的画面说“真的就像过电影一样。”救援队刚去的时候，洪水就在不停的上涨，当时就发现房屋的墙面已经开始有渗水，等到队员们成功将群众撤离，不到10分钟，房子就在洪水的冲击下全部倒塌。' },
      { type: 'p', text: '还有一次，苏琴和队友转移最后几名群众时，浪很大，水时不时溅进船舱，原本不肯转移上船的一个阿姨哭了，后怕得说不出其他话，上岸后一直不停地说“谢谢”……那一瞬间，苏琴觉得哪怕再辛苦，都值！' },
      { type: 'p', text: '7月22日，巢湖超历史最高水位，附近多处圩坝随时都可能溃口，尤其是顶托支流白石天河水位更是达到了13.56米。突然，防洪大堤处传来几声巨响，洪水像脱缰的野马冲开缺口，庐江县石大圩决口了！洪水四处肆虐，没过多久，5.8平方公里的范围内已是一片汪洋，周边4个行政村被淹。' },
      { type: 'p', text: '浑浊的洪水，表面是汪洋，实则暗流涌动。随着决口处面积再次扩大，眼见水流更加湍急。蓝天救援队连同消防、公安、水上救援队一起，分散在5艘冲锋艇上，打头阵的是消防员，苏琴坐在第2艘冲锋艇上。就在冲锋艇驶过连河村村委会附近时，急速的水流导致水位落差一下子从40公分猛涨到了3米多。“掉头、快掉头！稳住、快稳住！”一声嘶吼后，只见前方消防员乘坐的冲锋艇猛然侧翻，刹那间卷入汹涌湍急的洪流中，艇上5人瞬间一并消失在可怕的“滚水坝”。' },
      { type: 'p', text: '说时迟，那时快，紧随其后的苏琴高举右手，立刻向右前方猛打，“往右！往右！往右！”，在“前车”消失的同时，她大喊，舵手迅速改变前进方向，从“滚水坝”旁惊险地绕过……' },
      { type: 'p', text: '滚水坝有多可怕？由于存在落差，上游的水冲下去，和下一段低水位的水流形成反作用力，导致产生巨大的扰动，产生类似于滚筒洗衣机一样的翻滚效果。上下翻滚的水流，不像平面漩涡那样明显，往往水面比较平静，但水体之下却有暗流涌动。即便强壮如消防员，也会被这激流裹挟，失去自控能力。苏琴带着队友立刻从下游绕过滚水坝，开始搜救这5个消防员，最终，她和队友成功营救出3名落水消防员。' },
      { type: 'p', text: '在2020年汛期最吃紧的关头，苏琴带领合肥蓝天救援队累计出动救援人员824人次，转运受困群众517名，全员累计服务时长55296小时。' },
      { type: 'p', text: '回忆起当时，苏琴仍心有余悸：“这种大洪水，力量不可抗拒，当时的那种无助感，让我一辈子也忘不了。可即使再危险，那些消防队员们，还是在义无反顾向前冲，他们真的很伟大，总是在最前面，总是战斗在最危险的地方。”' },
      { type: 'p', text: '8月19日下午，苏琴在巢湖大堤罗家疃段见到了习近平总书记，总书记说，“今天是专程来看望大家，我要向全国奋战在抗洪抢险救灾一线的同志们，致以诚挚的问候！我们的广大干部群众、解放军、武警官兵，按照党和政府的要求，发扬不怕苦累、不怕疲劳、连续作战、不怕牺牲的英雄主义精神，充分体现了我们中华民族的众志成城，我们这个民族守望相助、洪水无情人有情的人间大爱。通过你们的斗争、奋斗、坚持、努力，我们在不断夺取抗灾、防洪、防汛的阶段性胜利。”' },
      { type: 'p', text: '“你知道我听完习总书记的讲话，内心有多激动吗？我们民间救援力量志愿者的行动，他都看到了。”一身蓝色队服的苏琴站在“人民英雄”当中，她当即暗自决心，要继续充电，通过不断学习，更好地带领团队发展，让合肥蓝天救援队的身影出现在更多的救援现场，帮助更多需要帮助的人。' },
      { type: 'h', text: '救人，越紧急时越要稳' },
      { type: 'p', text: '“我们这好好的，雨又不大，为什么要我们转移？”' },
      { type: 'p', text: '“我祖祖辈辈都生活在这里，这点雨没事，我都经历过，不会出大事的！”' },
      { type: 'p', text: '“你们也不容易，但我们真的是舍不得走啊……”' },
      { type: 'p', text: '又是一年7月，郑州大雨。当时，在苏琴带领下，19名擅长操舟、通讯、潜水及搜索等技能的队员，携带4艘冲锋舟，连夜驰援河南郑州。一条条街道，一户户人家，苏琴和队员将一个又一个被困群众安全转移。但在大多数情况下，“转移”工作并不容易。' },
      { type: 'p', text: '有时，上游已出现险情，但下游还风平浪静、毫无征兆。要说服还未亲眼见到危险的百姓搬出自己住了一辈子的家，看上去很是“无理取闹”。在紧张抢险的氛围下，人与人之间的沟通更是容易失去耐心。' },
      { type: 'p', text: '苏琴拿出手机，一边播放在上游抢险时录的视频，一边语速缓慢地解释：“大姐，您看看，这几十里开外的地方都被冲成这样了，这里也马上面临同样的危险。要是洪水没过来，我们再把大家送回来，要是洪水来了，我们也‘留得青山在不愁没柴烧’，回来重建家园。”百姓们听完，看着一个个嘴上干得起皮、汗水把救援服“染”成深蓝色的队员们，再不抱怨什么，转头回房间简单收拾，然后轻装上阵地跃入苏琴和队友的冲锋艇。' },
      { type: 'p', text: '做救援抢险工作时，最重要的是保持内心的平静和镇定，以便于关键时刻做出理性的判断，但往往人会在紧张的时刻变得情绪激动，甚至会莫名亢奋或是过度焦虑。尤其抗洪救灾的现场，闷热、潮湿，人又疲劳、着急上火，这几个因素一叠加，“真的像个炮仗，一点就爆！”男队员们事后笑嘻嘻地自嘲。' },
      { type: 'p', text: '队员小杨一路小跑到总指挥苏琴面前，急急忙忙地说了摸底情况。苏琴眼睛看着对方，扶了扶头顶的安全帽，然后一脸抱歉地把耳朵凑近说：“你刚才说得太快了，我没听清”，待小杨重复后，苏琴很快给出了对应的指示。其实，她第一遍就完全听清楚对方提供的所有信息，但觉得他太急躁，于是苏琴故意装作没听清，等小杨讲完后她还会故意压慢速度回答。' },
      { type: 'p', text: '“我平时讲话速度很快，但是在救援现场，我一般讲话会刻意放慢。”苏琴说，有时语速快也能把大家的节奏带得急躁。特别用对讲机去说话的时候，嘴比手快，刚一摁住侧键盘就开讲，往往前面的话都听不清。' },
      { type: 'p', text: '2013年12月初，救援队接到一个求助电话：一名78岁老人走丢了。苏琴和队友们急忙赶到现场，向老人的亲属了解情况，制定寻找方案，并分头行动。当晚9点，苏琴和同伴搜寻到一条干涸的小河沟时，发现走失的老人躺在沟底，气息奄奄。两天没进食，老人的身体已经很虚弱。苏琴脱掉自己的棉大衣给他穿上，急忙拨打120……所幸老人无大碍。' },
      { type: 'p', text: '后来接到的寻人求助多了，合肥蓝天救援队根据苏琴的提议，专门成立了一个“防走失小组”。利用无人机、无线电通信等技术，协助家属找寻走失人员。苏琴还想到为患有痴呆症的老人免费发放“黄手环”，上面有其亲属的联系方式、家庭住址等信息，一旦老人走失或发生特殊情况，他人发现后可以联系其亲属或帮忙送回。' },
      { type: 'p', text: '一次，苏琴又接到一个求助“寻人”的电话。电话另一端是一位老奶奶的声音，她情绪很急但话却喘得快不起来：“我的爱人趁我不注意走了，他留下一封信，请你们帮我找找他……”苏琴先来到家中，看着老奶奶一边摸索着老头每日使用的物件，一边向她诉说他的种种。原来，这位老人的爱人已经罹患绝症许久，由于处于癌症晚期，每天身上都很疼。老头腿脚不便，连起身上厕所都需要老奶奶艰难搀扶。老奶奶说着展开一封信，苏琴凑上前去一看，其实是一封遗书，不禁心里一沉，此次要寻的人已无“生”的希望。' },
      { type: 'p', text: '苏琴按信中所写找到老人选择“辞世”的地方，竟然看见一个干净的床单叠在岸旁。不禁感慨，即便自杀，老人都替别人着想周全。那时没有水下声呐探测器，苏琴和队友用工具在平静的河水下反复排查。' },
      { type: 'p', text: '“奇怪……”' },
      { type: 'p', text: '任凭苏琴和队友如何仔细搜寻，就是不见老人的“踪影”。苏琴心中盘算着老人从家走到这里的距离，虽然对常人不算太远，但对于连如厕都需要搀扶的人来说，能抵达水岸边就已筋疲力尽，应该不会再走远。这时，她想起老奶奶不经意间提过老伴年轻时游泳极好，是一名运动健将……苏琴瞬间“醒来”，顺着河岸一路找去，探查100多米后，她终于看见了“老人”。' },
      { type: 'p', text: '按照惯例，遗体打捞上岸后直接送至殡仪馆，再由家属去签字确认。然而，已经跟着一起来到岸边的老奶奶很想过去看看老伴的遗体，警察怕她情绪激动，或是再发生什么意外，不得不善意地拦截。此时，苏琴斗胆搀扶着老人，去和她的爱人做了最后的告别——亲爱的，我爱你！再见！' },
      { type: 'p', text: '老奶奶一字一顿地说出这几个字，没有号啕大哭，没有撕心裂肺，一切都是那么的平静……苏琴说，在队员打捞遗体时，老奶奶一直和她说着他们的过往，他们的生活，他们的爱情。对于老伴这样的选择，老奶奶内心很是理解，除了难过，她更庆幸爱人的解脱。' },
      { type: 'p', text: '为什么一个将自己双脚鞋带系在一起、决心求死的老人会在离“跳河”那么远的地方发现？苏琴百思不得其解。时过多年，她想通了，那是老人在决心不再拖累爱人、决定结束自己痛苦的生命前，最后再“浪”一次，再“畅游”一次人生，直到拼尽全力，直到生命的尽头……自杀，在这里不再是一个懦弱的选择，而是一种彪悍的人生态度。' },
      { type: 'p', text: '后来，苏琴时常同队员们讲起这个悲伤却又温情的故事。她想说，有时“人情”比“事情”本身大，除了遵守既定的规则，队员们更要看到冰冷事实背后的温情，那才是救人的真谛——除了拯救生命，还有人之常情。' },
      { type: 'h', text: '守家，珍惜爱的陪伴' },
      { type: 'p', text: '今年情人节前，苏琴明里暗里地向丈夫索要一份礼物——情书。谁能想到，一个参加救援数百次，一次次向险而行、逆流而上的救援队队长内心竟还还是这样一个感性、浪漫的“小女人”？' },
      { type: 'p', text: '在合肥新桥国际机场国际到达大厅，列队出来的14名队员收到了家属、队友和社会各界人士的鲜花、欢呼和掌声。' },
      { type: 'p', text: '苏琴的爱人陆海涛在人群中显得略高，只见他在接机口刚看到妻子“冒出来”，就赶紧走上前给她一个拥抱，并在她的脸颊吻了一下。“这次土耳其地震救援是苏琴所有救援行动中跑得最远的一次，我有点担心。看到她平安归来，我很高兴。”大胆示爱后的陆海涛又略显腼腆地对旁人解释起来。' },
      { type: 'p', text: '其实，苏琴每一次“出征”，不管车站、机场有多少人围观，陆海涛都会在众目睽睽之下、在离别的那一刻，抱住她、亲吻一下……一身合肥蓝天救援队制服的苏琴，瞬间没了“队长”的威风，在陆海涛怀里娇小得像个孩子。' },
      { type: 'p', text: '2016年4月23日晚，合肥大雨瓢泼，正在和儿子睡前聊天的苏琴，接到一个救援电话，一个老人在雨中走失。窗外，豆大的雨点打到玻璃上“哒哒”作响，一手搂着儿子的苏琴心立刻揪了起来：“儿子，你看下这么大雨，有一位老奶奶走失了，妈妈应该去帮忙找到她吗？”10岁的儿子懂事地点点头：“妈妈，你去吧。”' },
      { type: 'p', text: '这边，丈夫已经在帮苏琴收拾东西，麻利且郑重地递上包：“苏队长，动身吧！”平日里都喊“老婆”的陆海涛，每到此时就会用他那种理工男独特的幽默感给苏琴解压，一声带点调皮的“苏队长”，包含着信任、鼓励和不舍……' },
      { type: 'p', text: '丈夫照例亲了亲苏琴，看她安心地关门离去。门锁轻轻合上，苏琴赶紧用手摁住鼻梁，想止住泛酸的鼻头和要夺眶而出的泪水……人生无常，每一次的相聚，都可能是最后一次。这个道理在这个特殊的家里，无论大人还是孩子“都懂”。' },
      { type: 'p', text: '“老婆，我爱你！”' },
      { type: 'p', text: '“老公我也爱你哦！”' },
      { type: 'p', text: '这是苏琴和陆海涛每天在微信里都要来回重复、反复念叨的留言，结婚近20年，越是久越是这般“腻歪”。' },
      { type: 'p', text: '2003年的五一节，20岁出头、浑身是胆的苏琴报名参加大别山穿越活动。3天的穿越，让几个来自全省各地的年轻人从素不相识到“打成一片”。陆海涛就是其中一员，活泼开朗的苏琴“就像一束光”，让他眼前一亮。' },
      { type: 'p', text: '自带光环的女主角苏琴回忆说，当时没什么感觉，后来回忆了一下，对他的印象就停留在身前一个又高又瘦的背影——一个穿着登山鞋、背着登山包，一身T恤和牛仔裤，裤角还卷到小腿的阳光大男孩的背影。“也许是我后来给自己加戏了，这个背影给我留下了一点心动的感觉。”也许冥冥之中自有安排，20多年前的背影能在苏琴的脑海中如此清晰，那一刻的相遇不是爱情又是什么？' },
      { type: 'p', text: '3天的大别山穿越很快过去，分别前，苏琴的一个女性朋友故作神秘地眨眨眼，贴在她耳边说：“小陆看上去很不错哦！”大大咧咧的苏琴没有领会朋友的“话外音”，憨憨地回道：“嗯嗯，咱们这次表现都不错。”' },
      { type: 'p', text: '不久后，有“驴友”组织去合肥的董铺水库露营。听说苏琴要去，原本要加班的陆海涛二话不说就报了名。晚上，大家点起篝火，围坐在一起，有人提议玩“真心话大冒险”的游戏。“小陆，你喜欢哪个姑娘啊？”突然被问到这个问题，陆海涛有些紧张，但又暗自窃喜，停顿片刻，他果断地说出一个名字：“苏琴。”说完又马上紧张起来，抬眼看看苏琴，正好和她的眼神相遇。被火光照得陆海涛脸上红通通，心里怦怦跳，一下子被对面那双亮晶晶的大眼睛“击穿”，内心再次被这束“光”照得爱意涌动……' },
      { type: 'p', text: '渐渐地，两个年轻人走到了一起。用苏琴的话说：“他追了我好久！”2005年，苏琴和陆海涛喜结连理，一起步入婚姻的殿堂。第二年10月，儿子陆苏新出生。陆海涛的母亲特意从老家过来帮小两口带娃，苏琴和婆婆相处得十分融洽。住在一起十几年，婆媳间一次不愉快都没有，苏琴夸婆婆善解人意，陆妈妈说儿媳家里家外都是一把好手。' },
      { type: 'p', text: '不出任务的时候，苏琴就喜欢待在家里。好闺蜜一个电话打来，喊她出门小聚，她把电话靠近碗边，一边搅拌着她刚刚腌制的牛肉粒，一边得意地说“我今天专心陪老公和儿子，正准备做大餐犒劳这两个贤内助呢。”烧一手好菜，是除了“英勇”“坚毅”外，贴在苏琴身上的另一个标签。虽然在家的时间很少，但只要在家，她都亲自下厨，“投喂”家人。' },
      { type: 'p', text: '如今，在家做饭这件事她也需要“排队”了，马上要高考的儿子，突然爱上了烹饪。换作别人家的父母，肯定让孩子专心学习、备战高考，可苏琴和陆海涛二话不说，提上菜篮子就把儿子所列清单上的原材料统统买回了家。只听儿子独自在厨房里一通“捣鼓”，许久过去还不见美食，在沙发上相依看剧的苏琴转头看向“老陆”：“你儿子不会自己吃不叫我们了吧？”“怎么会！”陆海涛自信满满地回击了来自老婆的“嘲讽”。果然，儿子在认真地摆盘，等一切准备就绪，包括“让手机先吃”后，陆苏新大声喊来这两口子“尝尝鲜”。' },
      { type: 'p', text: '陆苏新从小就是一个不折不扣的学霸，苏琴常常忍不住向外人夸赞他的儿子是“天牛”——天生的“牛”娃，既继承了爸爸聪慧的大脑，又继承了妈妈过人的体能。“我从来都没管过他”，听苏琴和电话里的友人又一次“显摆”，一旁的“老陆”终于忍不住了，等老婆电话挂断，坐到其对面，看着苏琴认真地说：“你有没有想过是我教子有方？”苏琴看着严肃起来的老公，“噗嗤”一声笑了出来。' },
      { type: 'p', text: '她当然知道是丈夫在背后的付出！自己不在家的时候，谁来辅导作业，给孩子养成最初良好的学习习惯？谁来照顾偶尔头疼脑热的老人，为其修缮好家中的小物件？每次和闺蜜们聚会，苏琴都忍不住夸赞自己的老公。一次，好闺蜜和丈夫闹不愉快，找姐妹们出来“吐槽”。苏琴刚一坐定，身旁的闺蜜赶紧伸手捂住她的嘴：“今天只准说老公的缺点，你少说话！”' },
      { type: 'p', text: '有趣的是，结婚十余年来，苏琴和丈夫没有一次记住结婚纪念日，经常是过了好久了才突然想起，然后两个人哈哈大笑……去年的纪念日，苏琴难得记住了，可是却遇上了救援任务，爱人只好在现场的警戒线外面焦急地等待着，等苏琴终于安排好现场的一切事务后，已经是饥肠辘辘了。一身汗水一身脏，她和爱人就在附近的大排档找了一个安静的位置坐下。谁知刚坐下，苏琴就本能地掏出手机给刚刚也忙完救援任务的队友打了过去:“你们还没有吃饭吧?我们就在附近的烧烤店，一起过来吃吧”话音刚落，丈夫怔怔地盯着苏琴，苏琴也瞬间明白过来，“我这是在干吗?不是庆祝结婚纪念日的二人世界吗?”于是两人又哈哈大笑起来….' },
      { type: 'p', text: '在他们眼里，能一起去取个快递、买个菜，过着平凡的小日子，用支持鼓励和幽默风趣的方式，将每一天过成“纪念日”的模样才最有意义。' },
      { type: 'h', text: '做人，眼里有光、心中有爱' },
      { type: 'p', text: '1980年2月，苏琴出生在安徽省青阳县一个普通的公务员家庭。“你能想象吗？”苏琴和儿子描述着儿时记忆中的“年味”。' },
      { type: 'p', text: '大年三十，又圆又大的餐桌上，毛豆腐、臭鳜鱼、一品锅、土鸡汤……苏琴的七大姑八大姨各个是“巧厨娘”，不一会儿大家凑出一桌丰盛的年夜饭。看大人孩子都到齐了，外公缓缓地从里屋跨出来，他让儿子和儿媳、女儿和女婿都围在圆桌而坐，孩子们在隔壁一个小方桌旁坐好，唯独他站着……' },
      { type: 'p', text: '“年夜饭前，我们照例开个家庭会议，今年的主题是‘遵守党的纪律’……”外公说着摊开自己的笔记，开启一年一度的“思政课”。在苏琴的记忆里，外公手里永远握着一份《参考消息》，那是外公退休后始终坚持翻阅的报纸，里面总有他认为重要的理论和消息。外公十分看重廉洁守纪，他常常“敲打”在体制内工作的儿女，不能拿公家一分钱，不能占百姓一点便宜，要团结友爱、维护公德、帮助他人……' },
      { type: 'p', text: '在这股“正能量”的家庭氛围熏陶下，苏琴从小就正直善良，为人坦荡。初到合肥上学，她感觉第一次离家的自己“长大了”，脑子里冒出一个想法——自己也要像家中长辈一样“做一个好人”。于是她打开崭新的日记本，一笔一划写下“每天做一件好事”。' },
      { type: 'p', text: '第二天出门，她顺手带走了楼道中邻居的垃圾，过马路时发现一位需要搀扶老人，上学的路上捡到随意乱丢的易拉罐……一天下来，竟做了不少“好事”！晚上洗漱完毕，苏琴躺在自己用砖头当床腿“找平”的木板床上，心里觉得美滋滋的，一翻身便踏实地睡着……' },
      { type: 'p', text: '学习财务的苏琴，毕业后来到一家装修公司做财会人员。“小姑娘做财务挺好”，同事们看着这个初来乍到的女孩文文静静地坐在办公桌前，认认真真地对账，怎么也想不到日后她会是一个专门负责抢险救灾的救援队队长。' },
      { type: 'p', text: '其实，苏琴的“彪悍”很快就在公司“露馅”。通常干财务的人都“长”在座椅上，每天写写算算。苏琴不这样记账，她跑去工地，看工人具体如何装修房屋，看每一笔开支都是如何花出去的，具体做了什么用途。很快，苏琴的账记得准确、合理，令同事们刮目相看。' },
      { type: 'p', text: '一次，公司原本承包的大型装修项目被“毁约”，造成500多平方米的原木地板无处“消受”。已略懂装修的苏琴大胆地将这些当年被视为“上档次”的木地板全部承接下来，她发动家里亲戚，看看谁家需要铺地板，她以“腰折”零售价为大家装修。' },
      { type: 'p', text: '炎炎夏日，苏琴头顶火热的太阳坐在平板货车上，“护”着她身后的地板，一路从合肥回到老家青阳。卸货后，她和工人一起上楼入户，先是把卧室中所有的家具移走，再一丝不苟地将水泥地面清扫干净。正式开工前，她用提前备好的大块塑料布，仔细罩住所有家具和家中其余的边边角角。铺就好一个房间，再如法炮制铺另一间，一天时间内，这家“焕然一新”，同时还一尘不染。' },
      { type: 'p', text: '苏琴前脚一走，亲戚后脚就给苏琴的父亲打去了电话：“你女儿太能吃苦了！一直蹲地上和工人一起干活，特别麻利……”父亲闭上眼睛，想象着自己养大的这个外表看似柔弱，实则内核坚毅的女儿，幸福地嘴角上扬。' },
      { type: 'p', text: '回到合肥，苏琴不仅解决了公司的“难题”，还获得了自己的“第一桶金”。第一次看到账户上有了4个零，苏琴初尝勤劳的甘甜。结果，一则招募户外驴友的信息彻底为苏琴推开了一扇“天窗”，从此踏上了一条为情怀买单的路。' },
      { type: 'p', text: '手头有点积蓄的苏琴忽然爱上了户外，从2004年开始，她登过三座雪山，穿越过三大无人区，徒步沙漠，走了7次西藏，自驾过欧洲……用她的话说：“总之在没有接触救援工作之前，我叫一个潇洒啊，不是在旅行的路上，就是在电脑前做着各种旅行的攻略。”' },
      { type: 'p', text: '后来，苏琴实在太喜欢户外运动，干脆离开装修公司，自己创业开了一家户外俱乐部，组团带队翻山越岭。一次，她和几个朋友一起徒步徽杭古道，遇到芜湖的一个团队在寻人，原来他们的一个队友在下山时走散了。彼时天色渐晚，山上没有手机信号，苏琴和朋友很快自愿加入寻人的队伍。幸运的是，当晚就找到了走散的队员，有惊无险。然而，那次经历却让苏琴强烈感受到救援工作的重要性，通过做公益来帮助他人的理想，在那个时候悄悄萌芽。' },
      { type: 'p', text: '2012年，合肥市蓝天救援队成立，32岁的苏琴成为初创成员之一，也是队里唯一的女队员。前3年，救援队的事情不太多，她在游泳、驾船、潜水、陆搜、急救导师等多重角色中打磨自己的救援技术，练成了“全能型选手”。直到2015年，前任队长卸任，她在众人的无记名投票中当选为队长。' },
      { type: 'p', text: '2016年，在长江安庆段，四名少年溺水失踪，经过三天的全力搜救，少年遗体全部被打捞上岸。“遗体是找到了，可是人却再也不能复生啊，看着岸上悲痛欲绝的父母，在路上我就想，我们一定要做点什么？”' },
      { type: 'p', text: '回合肥后，苏琴去向上级主管单位汇报工作，谈起这件事情，领导提醒她说，你们可以在平时做一些防灾减灾的宣讲。就这样，苏琴和救援队进村入校宣讲防溺水工作在2017年开展了起来。' },
      { type: 'p', text: '讲台上，一个穿着印有“熊孩子”字样衣服的队员假装笨拙地在水边反复试探，滑稽的动作和搞笑的表情逗得全场学生哈哈大笑。“哈哈哈……”紧接着是更开怀的一阵大笑，原来，身穿“熊家长”的队员上台了，他领着孩子来到竖有“严禁在此游泳”的小河边，“噗通”地“跳”入水中……' },
      { type: 'p', text: '这是苏琴和队员们根据一个个真实惨案改编的情景剧，为了能引起孩子的警醒，减少悲剧的发生，他们既保留严肃认真的说教，也加上轻松活动的互动。这项工作一做就是8年，截至目前，共完成1900场宣讲，受益中小学生170余万人。在苏琴和队友们的努力下，合肥市中小学生由意外引发的溺亡逐步下降，这令苏琴感到无比欣慰，也觉得团队做的事情很有意义。' },
      { type: 'p', text: '好多人问苏琴，你一个女人，冲锋在前不害怕吗？她笑一笑，心想我怎么会不怕呢！' },
      { type: 'p', text: '“绳索救援”是救援工作者的基本功，基础线路搭建、上升下降过保护站、横移线路搭建及通过、竞技过U、1对1救援……在这些技术培训考核中，苏琴都曾展示过矫健的身手，但她还是最怕“磨绳”。实际救援中，绳索很容易与陡峭的岩壁产生摩擦，救援队员在下降的过程中，绳索会随着负重加大，与岩壁拐角的磨损效应越强，甚至可能切断绳索。苏琴最怕救援变成“葫芦娃救爷爷”，救不成人还把队员搭进去。因此平日训练中，苏琴总是反复强调“再多打一个固定点”，“那种命悬一线的感觉太可怕了……”' },
      { type: 'p', text: '危险来临的时候，谁都会怕。只是面对危险和害怕，苏琴选择坦然以对。她坦诚地说，大家都有爱人有孩子有父母，身上都有着不一样的责任，但到了救援现场，根本就想不来那么多，只想着怎么把事情做好，如果真有危险，我是队长，我必须上。' },
      { type: 'p', text: '还记得一次抗洪抢险中，堤坝出现“管涌”，眼看稳固的河坝很可能变成一个威力巨大的“不定时炸弹”。队员小李急了，大声冲苏琴喊去：“我现在不喊你队长了，你是女的，女的先走，赶紧走！快，大家赶快把这个女的拉走……”' },
      { type: 'p', text: '“我是队长，危险时刻我必须第一个冲在前面！”这位在救援一线默默耕耘的巾帼英雄，以智慧、勇气和不懈努力，构筑了合肥蓝天救援队的坚实脊梁。她深知，每一次救援行动都是对生命的尊重与守护，因此，无论面对多么艰难险阻，她都义无反顾地冲在最前，用实际行动诠释了“以人为本，生命至上”的崇高理念。' },
      { type: 'p', text: '在苏琴的带领下，合肥蓝天救援队不仅成为了当地乃至全国范围内的一支重要救援力量，更成为了传递爱心、弘扬正能量的重要载体。她和队友们的事迹被广泛传颂，激励着更多人关注公益、投身救援事业，共同为构建和谐社会贡献自己的力量。' },
      { type: 'p', text: '2023年11月，苏琴当选为中国妇女十三大代表。会上发言时，她由衷地说：“在救援现场做一个女汉子，在日常生活中做一个小女人。”如今，已有越来越多的女队员加入蓝天救援队，在工作中，她们是警察、是律师、是医生，在生活中，她们是妈妈、是女儿、是妻子，但在救援中，她们就是女英雄……' },
      { type: 'p', text: '“我们从未被定义，也从未敢懈怠，我有前进一寸的勇气，也有后退一尺的从容。我们用自立、自信、自尊、自强，书写美丽篇章，以无私、无怨、无悔、无惧，展现巾帼绽芳华的女性力量。”' },
      { type: 'p', text: '苏琴和越来越多的姐妹用自己的实际行动证明了，即使是最平凡的女性，也能在各自的岗位上展现出非凡的力量和光芒。她们勇敢的践行和无畏的精神将永远激励着后来者，在未来的道路上继续前行，为守护生命、传递爱心而不懈努力。' },
    ],
  },
  {
    id: 'fan-kexin',
    kind: 'profile',
    date: 'Feb 16, 2022',
    read: 9,
    lang: 'zh',
    illus: 'assets/illustrations/still-life.svg',
    heroIllus: 'assets/illustrations/still-life.svg',
    title: '范可新："输"在起跑线上却一路"可新"',
    titleEn: 'Fan Kexin · Losing at the starting line, winning anew',
    dek: '七台河女孩范可新，用冰刀切开命运的冷硬，一路"输"着，也一路赢着。',
    tags: ["profile","冬奥","短道速滑","金牌"],
    body: [
      { type: 'p', text: '2月5日，在北京冬奥会短道速滑男女2000米混合接力项目中，范可新与队友为中国队斩获本届冬奥会首枚金牌。10天后，本刊记者独家专访范可新的母亲，来听听奥运冠军的“养成记”。' },
      { type: 'h', text: '范可新：“输”在起跑线上却一路“可新”' },
      { type: 'p', text: '“范可新，你终于圆梦了！”冬奥会斩获一金一铜的范可新深情亲吻冰面的镜头，令多少人动容……' },
      { type: 'p', text: '短道速滑混合接力赛，是北京冬奥会短道速滑项目第一场决赛，更是中国代表团首个冲金项目。范可新和队友们承担的重任和压力可想而知，经过了两届冬奥会和无数场世界杯、世锦赛磨砺的范可新， “第一棒”发挥出惊人的爆发力，在外道起跑的劣势下为后续队员争取更好的道次。等到她再次接棒时，更是拼尽全力，肉眼可见的把微弱优势拉成了绝对优势，以最快的速度稳准狠地传递给下一棒……那一夜，中国代表团首金诞生。范可新和队友在赛场上高高举起五星红旗，任泪水奔涌……' },
      { type: 'p', text: '要让家人过上好日子采访中，范可新的母亲聂桂玲数次哽咽，在她看来，别人家的父母都要让孩子赢在起跑线上，自己却让孩子“输”在了起跑线上，因此，一直内疚。' },
      { type: 'p', text: '黑龙江省七台河市，一个常住人口不到70万的小城，先后培养出了张杰、杨扬、王濛等10位世界短道速滑冠军，网友们戏称“此地特产——冬奥冠军”。然而，三十多年前，因为生意失败，带着仅剩的500元从老家来到这里的聂桂玲夫妇万万想不到，女儿范可新也将在这里开启世界冠军之旅。' },
      { type: 'p', text: '他们靠修鞋维持生计，懂事的范可新从不向父母要零花钱，甚至在放学路上，她还会捡可以回收的垃圾贴补家用。' },
      { type: 'p', text: '年幼的范可新喜欢跳舞，学校舞蹈老师夸赞她是个好苗子，柔韧性好，比别的孩子能吃苦。然而只学了一个月，她就死活不去上课了。聂桂玲以为女儿对舞蹈不感兴趣，想起每次路过离家步行5分钟的体育场，总能看到一帮孩子在跑步，她琢磨，女儿体弱，能不能跟着一起跑步锻炼身体呢？她带着女儿去了，才知道这是市体校业余短道速滑队在训练。当时执教的马庆忠教练见了9岁的范可新，先让她跑了几圈，又让她跳了几下，再问她喜不喜欢，没想到这个瘦弱的女孩儿先问了一句：“学这个要交钱吗？”原来，范可新放弃学跳舞的原因正是因为老师通知她交学费，她不想给家里增加负担。马教练看出了这个家庭的拮据，更看出孩子的早熟和懂事，他不但当场承诺不收钱，日后更是自掏腰包买了一双二手冰鞋送给她。' },
      { type: 'p', text: '当马教练告诉范可新，短道速滑名将大杨扬就是从这里走出去的奥运冠军，滑好冰不仅可以为国争光，也能挣钱改善生活状况，范可新决定练习滑冰，只因心中那个愿望——让家人过上好日子！' },
      { type: 'h', text: '越努力越幸运' },
      { type: 'p', text: '于是，在最贪玩的年纪，范可新每天除了学习，就是日复一日枯燥而繁重的体能训练。每天凌晨4点起床赶到体育场训练，6点回家吃早饭后去上学，下午3点半放学后再去体育场练到晚上6点半。她每天都给自己上闹钟，害怕错过任何一次训练。 “每天放学回家扔下书包就往体育场跑，舍不得耽误一分钟。”' },
      { type: 'p', text: '当时没有室内冰场，孩子们一年四季几乎都是在旱地训练，而真正能上冰也就是一年中零下30多度的冬三月。“寒风中孩子们嗖嗖滑，该怎样遭罪可想而知。”聂桂玲至今想起满是心疼。' },
      { type: 'p', text: '因为穿着不太合脚的二手冰鞋，范可新的脚总是磨得血肉模糊，父母心疼得一起“劝退”，范可新从此不允许妈妈看伤口。“没办法，我和老伴都是等女儿睡着了，偷偷掀起她的被子，先看胳膊再看腿，看完膝盖再看脚，一边看一边哭……”' },
      { type: 'p', text: '成功入选省队后，范可新需要一双正规的专业冰鞋，还有一年2500元的学费……沉重的经济负担让聂桂玲一家犯了愁。省队主教练孟庆余了解情况后说，学费不能免，但他会自己送给范可新一双新冰鞋。2500元的冰鞋，甚至超过当年一年的工资。或许是越努力越幸运，范可新两度遇到对她有知遇之恩的启蒙教练，至今范可新一家充满感恩。' },
      { type: 'p', text: '为免去无证经营被查处罚款的风险，聂桂玲到工商所办理修鞋铺的营业执照，她一脸愁容被工商所孙玲所长看在眼里。得知这家人的困境，她先是免去了聂桂玲办证的手续费，又发动亲朋好友募捐2500元，替范可新交了第一笔学费。自此，范可新的学费和生活费都是孙所长和丈夫承担，直到她入选国家队。' },
      { type: 'p', text: '聂桂玲说，这七年谁都不知道范可新的未来会怎样，更不会想到她能成为世界冠军，帮助范可新的好心人因为她的懂事和坚韧，盼她梦想成真。' },
      { type: 'p', text: '而知恩图报是这个朴素家庭坚守的原则，范可新训练更是不遗余力。' },
      { type: 'h', text: '这只是一个开始' },
      { type: 'p', text: '如愿进入国家队后，范可新终于不用他人接济了，省吃俭用的她反而能经常反哺家里。虽然她离“让家人过上好日子”的梦想近了，却离家人越来越远了。在跟随国家队到处征战的12年里，范可新一直没能和父母一起过春节，更是难得回家团聚。她不是在比赛，就是在准备比赛。而范可新的梦想也早已从“为家争福”变成了“为国争光”。' },
      { type: 'p', text: '向来报喜不报忧的她再也没让母亲见过身上的伤，更不会让母亲知道这12年里，通过残酷紧张的训练和大大小小的比赛，她如何从一个落后的边缘队员成长为冲击金牌的种子选手。但知女莫过母，即便什么都不说，范可新还是被母亲一针见血地指出“思想包袱太重，太急于求成”的心理弱点，以至于在前期的一些大赛中发挥不出真实水平。' },
      { type: 'p', text: '在教练、队友和家人的帮助下，范可新不断调整状态，突破极限，凭着一股对自己的狠劲儿，一步一刀地拼出了一个“中国短道新领军者”的范可新，在一次次世锦赛中刷新和保持着世界纪录。' },
      { type: 'p', text: '备战北京冬奥会，范可新当仁不让地接下了可能创造历史的“第一棒”。挤在范可新家里一起观看冬奥直播的亲朋好友无不提心吊胆，随着她的冰刀在赛道上霸气地一戳，扎实奋力地蹬出第一步、第二步、第三步…… “他们都不敢眨眼，紧盯着电视屏幕，感觉心跳比我姑娘还快。”回忆女儿夺取首金的那场比赛，聂桂玲笑了。夺冠的一刹那，大家欢呼雀跃高声呐喊。' },
      { type: 'p', text: '事后聂桂玲得知，就在这场夺金大战的前十天，范可新因旧伤复发，接受了紧急治疗，在命悬一线的最后关头，范可新就一个字：“拼”！' },
      { type: 'p', text: '由于疫情防控的原因，参加本届冬奥会采取闭环管理，赛后一直隔离的范可新，解除隔离还要再战一次世锦赛才能回家，家人们都在数着日子等待着她的归来。除了嫂子做的“下车面”，母亲做的她最爱吃的地三鲜，父亲还要为她燃放鞭炮。父亲在范可新的心里，就是一棵大树。“我老爸干啥像啥！”邻里街坊都愿意到老爸的摊位上配钥匙、修鞋、修自行车，父爱给了范可新“拼”的力量。而年幼的范可新在冰场滑冰，母亲就在冰场外跟着她一圈一圈地跑……来自家庭的爱与支持，正是她向上生长的“沃土”。' },
      { type: 'p', text: '“我真心希望她能就此好好歇一歇。”母亲的愿望极其简单，但对范可新来说，只要国家队需要，她必当鞠躬尽瘁，正如她亲吻挚爱的冰面后所说：“这只是一个开始。”' },
    ],
  },
];

